quests[29594] = { id = 29594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting Them Where It Hurts", description = "The fel orcs have stockpiled many of their supplies here.\n\nStealing them would be a severe blow to their war effort and a great boon to ours. Are you up to the task, {class}?", sourceObjective = "Steal 3 piles of Hellfire Supplies, then return to Advance Scout Chadwick in Hellfire Ramparts.", progress = "How many piles were you able to take?", completion = "Well done! The long term effects of this attack will be far worse than slaying a few orcs could ever be.", sourceObjectiveStatus = "unverified-source-field" }
quests[29595] = { id = 29595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything Will Be Alright", description = "You've had quite an adventure, {name}. And before you've even set foot inside of the Auchenai Crypts.\n\nI am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar's vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts.\n\nWhat I ask is simple. Enter the Auchenai Crypts and speak with the Draenei Spirit there. You must destroy Exarch Maladaar.", sourceObjective = "Greatfather Aldrimus standing outside the Auchenai Crypts of Auchindoun has asked that you enter the Auchenai Crypts and speak with the Draenei Spirit.", completion = "Welcome to the Auchenai Crypts, {name}, where our two worlds meet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29596] = { id = 29596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of the Exarch", description = "Exarch Maladaar performs his unholy work in the deepest part of the crypts. He poses a threat to both of our worlds if he is not stopped.\n\nYou must slay him for the benefit of us all, dead and alive.", sourceObjective = "Kill Exarch Maladaar and return to the Draenei Spirit inside the Auchenai Crypts.", completion = "You have done our realm a great service. You will not be forgotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29598] = { id = 29598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taretha's Diversion", description = "It was Taretha who created the original diversion at Durnholde, allowing Thrall to escape.\n\nNow the Infinite have captured Taretha. The diversion will not happen without our involvement. You must use the incendiary devices that I give you and burn down the internment lodges.", sourceObjective = "Travel to Durnholde Keep and set 5 incendiary charges at the barrels located inside each of the internment lodges using the Pack of Incendiary Bombs given to you by Erozion.\n\nSpeak to Thrall in the basement prison of Durnholde Keep when you have the Internment Lodges Set Ablaze.", progress = "Who are you?", completion = "You are friends of Taretha? So this is her new plan? Very well then...", sourceObjectiveStatus = "unverified-source-field" }
quests[29599] = { id = 29599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Durnholde", description = "I have plans for my people, stranger.\n\nOne day, they shall overthrow their oppressors and rise as one. They will break free from the bonds that hold them and from that uprising shall be born the orcish Horde.\n\nWe will leave when you are ready.", sourceObjective = "When you are ready to proceed, let Thrall know. Follow Thrall out of Durnholde Keep and help him free Taretha and fulfill his destiny.\n\nSpeak with Erozion in Old Hillsbrad should you complete this task.", completion = "You have done a great thing, {name}. Alas, the young warchief's memory of these events must be as they originally were...", sourceObjectiveStatus = "unverified-source-field" }
quests[29600] = { id = 29600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snap Judgment", description = "These pools are very special: they nurture life like nothing else in Pandaria.\n\nUnfortunately this means they draw all kinds of attention from local fauna. Recently, dragon turtles have discovered that toadspawn pools are common on the tier just above us. They're running wild up there, trampling the lotuses and snapping at my workers.\n\nThey aren't much of a threat on their own, but in groups they can be pretty nasty. Please, if you can spare your strength, help clear them out.", sourceObjective = "Kill 16 Razorback Snappers at the Pools of Purity.", progress = "<Yue sighs.>\n\nIf only we'd kept up with our maintenance, the situation would not have come to this.", completion = "You have my gratitude, {name}.\n\nPlease take this as a token of my appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[29605] = { id = 29605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Against Brother", description = "The Sethekk departed Skettis when Auchindoun exploded.\n\nMy brother, Syth, was one of their leaders and told us we had to go into the ruins and face our god.\n\nIn time, Syth had me cast out of the Halls for doubting them, but he refused to let me take our sister Lakka. Will you help me rescue her?", sourceObjective = "Free Lakka from captivity. Return to Isfar inside the Sethekk Halls when you've completed the rescue.", completion = "Knowing that Lakka is free means I can cut the rest of my ties to the Sethekk.\n\nPart of me will never forgive myself for Syth's death, but it had to be done. When I reach Skettis, I will perform the death rites for him.", sourceObjectiveStatus = "unverified-source-field" }
quests[29606] = { id = 29606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokk's Legacy", description = "Terokk, hero of the Arakkoa, mysteriously vanished one day, leaving only his mask and spear behind.\n\nDarkweaver Syth still holds his mask and Talon King Ikiss guards his spear.\n\nIt would mean a great deal to my people if these items were returned to us.", sourceObjective = "Bring Terokk's Mask and Terokk's Quill to Isfar inside the Sethekk Halls.", progress = "The relics of Terokk have been absent from Skettis for too long. Were you able to recover them from the Sethekk?", completion = "I may never truly be forgiven for my role in the crimes of the Sethekk, but perhaps by restoring the relics of Terokk to my people, I can begin to redeem myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[29607] = { id = 29607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of Desire", description = "I have a buyer who is interested in the eyes of the Cobalt Serpents that have taken up residence here.\n\nIf you were to bring me some of these rare gems, I would cut you a portion of the profits.\n\nDo we have a deal?", sourceObjective = "Dealer Vijad inside the Sethekk Halls wants you to bring him 3 Cobalt Eyes.", progress = "Did you bring the eyes?", completion = "These are marvelous. Well done!\n\nHere's your cut, as promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[29608] = { id = 29608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies in Dalaran", description = "Welcome to Northrend, {name}. I have been asked to arrange travel for you to Dalaran so that you can meet with our allies there.\n\nRide the gryphon to Dalaran and once you land, make your way to our inn there, A Hero's Welcome. Find Isirami Fairwind and speak with her immediately.\n\nShe can help you bind your hearthstone to the city so you can use the Silver Enclave's portal to travel back to Stormwind quickly.", sourceObjective = "Accept a gryphon ride to Dalaran and speak with Isirami Fairwind at A Hero's Welcome.", completion = "Welcome to Dalaran! This inn is part of the Silver Enclave, the headquarters of the official Alliance presence in our city.\n\nDon't forget to bind your hearthstone here for easy travel to the city and access to the portal to Stormwind next door.", sourceObjectiveStatus = "unverified-source-field" }
quests[29609] = { id = 29609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends in Dalaran", description = "Welcome to Northrend. I have been asked to arrange travel for you to Dalaran so that you can meet our friends in the city.\n\nSpeak with me and accept a ride to Dalaran. Once you land, make your way to The Filthy Animal.\n\nMake contact with Uda the Beast immediately.\n\nShe can help you bind your hearthstone to the city so you can use the portal in Sunreaver's Sanctuary to travel back to Orgrimmar quickly.", sourceObjective = "Accept a ride to Dalaran from the flight master and speak with Uda the Beast at The Filthy Animal.", completion = "I've been expecting you! This inn is part of Sunreaver's Sanctuary, the Horde's enclave in Dalaran.\n\nDon't forget to bind your hearthstone here for easy travel to the city and access to the portal to Orgrimmar, out by the fountain.", sourceObjectiveStatus = "unverified-source-field" }
quests[29611] = { id = 29611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of War", description = "Lok'tar ogar, {race}. I am Nazgrim.\n\nYou are hereby ordered to present yourself to Garrosh Hellscream at Grommash Hold immediately.\n\nBy his decree, all in service to the Horde are to swear an oath of allegiance to their new Warchief.\n\nDo not keep him waiting, {race}.", sourceObjective = "Speak to General Nazgrim in Grommash Hold", progress = "Blood and thunder, {race}.", completion = "Ahh, good. You're here. And not a moment too soon...", sourceObjectiveStatus = "unverified-source-field" }
quests[29612] = { id = 29612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of War", description = "Lok'tar Ogar, old friend. It has been too long since last we spoke.\n\nIt is good to see that you emerged safely from the depths of Vashj'ir.\n\nWarchief Hellscream has stationed me here in Grommash Hold.\n\nBy his decree, all in service to the Horde are to swear allegiance to their new Warchief.\n\nYou would do well not to keep him waiting, {name}.", sourceObjective = "Speak to General Nazgrim in Grommash Hold in Orgrimmar.", progress = "Blood and thunder, {name}!", completion = "Ahh, good. You're here. And not a moment too soon...", sourceObjectiveStatus = "unverified-source-field" }
quests[29613] = { id = 29613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Fate", description = "Warlord Kalithresh is in charge of the entire Steamvault operation.\n\nI need you to kill him, {name}. The naga have left us with no option but violence.\n\nShow him no mercy.", sourceObjective = "Kill Warlord Kalithresh and return to Watcher Jhang inside the Steamvault.", completion = "I wish it had not come to this, but the naga refused all attempts to negotiate.", sourceObjectiveStatus = "unverified-source-field" }
quests[29614] = { id = 29614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containment is Key", description = "The naga are working with leper gnomes to spread a horrific disease across Zangarmarsh. It's already spread throughout the Steamvault.\n\nClear out anything that's been contaminated and bring me the central gear from Mekgineer Steamrigger, quickly!", sourceObjective = "Kill 3 Bog Overlords, 6 Coilfang Lepers, and obtain an Irradiated Gear from Mekgineer Steamrigger, then return to Naturalist Bite inside the Steamvault.", progress = "Be as thorough as possible. The fate of Zangarmarsh depends on it.", completion = "I'm glad we were able to contain this before it spread across all of Zangarmarsh or further. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29615] = { id = 29615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windcaller Claw and the Water Thief", description = "The Steamvault is the heart of the naga's efforts to pump the water out of Zangarmarsh, and Hydromancer Thespia personally oversees those efforts.\n\nTaking her out would seriously hinder their operation.", sourceObjective = "Kill Hydromancer Thespia and return to Windcaller Claw inside the Steamvault.", progress = "Did you dispatch of the water thief?", completion = "Perhaps now we can restore all of the desperately needed water to the land.", sourceObjectiveStatus = "unverified-source-field" }
quests[29616] = { id = 29616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming the Steamvault", description = "We have not as of yet been able to stop the naga in the Steamvault, where most of their pumping infrastructure is located.\n\nThankfully, the expedition I sent there is hard at work trying to change that fact. Will you travel to the Steamvault and offer Watcher Jhang and her crew your aid?", sourceObjective = "Speak with Watcher Jhang in the Steamvault.", completion = "Thank the stars you're here. We need your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[29617] = { id = 29617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tian Monastery", description = "People come from all over Pandaria to train at the Tian Monastery, just to the north of here. Probably because they never turn anybody down. They'll accept jinyu, hozen... or even a foreign {race} like you!\n\nMy childhood friend, Lin, just joined the monastery's order a few weeks ago. If you're interested in learning how our monks train, maybe you should go talk with her!", sourceObjective = "Speak with Lin Tenderpaw at the Tian Monastery in the Jade Forest.", completion = "You've arrived at an exciting time. High Elder Cloudfall has agreed to take on a new class of trainees within the monastery. This could be my big chance to finally learn how to fight!", sourceObjectiveStatus = "unverified-source-field" }
quests[29618] = { id = 29618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Elder", description = "How strange, to have such a foreign-looking {class} visiting our temple. Are you here to study?\n\nYou... you look very strong. You wouldn't have any trouble getting accepted into the monastery. You should talk to the High Elder, up on the balcony above.", sourceObjective = "Speak with High Elder Cloudfall at the Tian Monastery in the Jade Forest.", completion = "Welcome to Tian Monastery. I see young Lin has helped you understand the role we fill here in our hilltop village.\n\nWe are unaccustomed to outsiders. You would do us a great honor to train alongside our younglings. We do not have anything to offer you, {class}... except knowledge, and perhaps an appreciation of what it means to be pandaren.", sourceObjectiveStatus = "unverified-source-field" }
quests[29619] = { id = 29619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Courteous Guest", description = "I heard, I heard! The High Elder wants you to train with us!\n\nThere's going to be a banquet for us, the trainees... and you should probably bring a gift, as a sign of courtesy.\n\nThe oranges in the grove south of the temple are extra-sweet right now. Bring some back, for the banquet.", sourceObjective = "Gather 8 Ripe Oranges from the orange groves south of Tian Monastery.", progress = "Are you ready for the banquet? I can't wait.", completion = "These will do perfectly. What a thoughtful gift, {name}!\n\nMe? I'm bringing beer, of course.", sourceObjectiveStatus = "unverified-source-field" }
quests[29620] = { id = 29620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Banquet", description = "The banquet should be starting any time now. Go find the High Elder and pay your respects. I'll be right behind you.", sourceObjective = "Speak with High Elder Cloudfall at the banquet grounds in the Tian Monastery.", progress = "We will move on to the training soon enough, young {class}. First, we must talk, and drink, and eat.\n\nThough I must say, I admire your discipline.", completion = "That concludes our introductions. You should be ready to begin your training.\n\nThat is... you should be ready to begin your training... AFTER we have one more mug of ale. Perhaps two. Shall we, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[29622] = { id = 29622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Training Starts Now", description = "<Xiao does not look up from his bowl.>\n\nHey, new <guy/lady>! Glad to see you survived the banquet! Trial One: Complete!\n\n<Xiao eats noisily.>\n\nYou'd better speak up with Instructor Xann. He'll be expecting you for your daily exercises.\n\n<He continues eating. You suspect that he is done talking to you.>", sourceObjective = "Report to Instructor Xann at the Tian Monastery in the Jade Forest.", completion = "First, you drink too much beer... and then you show up to class late? Looks like you've already conformed to pandaren culture.\n\nLet's begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[29623] = { id = 29623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfection", description = "Perfection can be achieved through repetition. Every single student in the training arena below will eventually perfect his or her form... assuming they don't give up first. This is a fact.\n\nI encourage you to join them, {name}. As an honorary guest of the monastery, you are not required to perform the requisite 10,000 daily strikes. Simply follow the leader's example for a few minutes.", sourceObjective = "Perform 12 practice strikes in the Monastery Training Arena by following the leader's example.", progress = "I, too, once trained in this very arena. Times were simpler then.", completion = "This isn't your first time fighting, is it? Your form isn't perfect, but it is certainly practiced.", sourceObjectiveStatus = "unverified-source-field" }
quests[29624] = { id = 29624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attention", description = "Your next test also involves concentration and attention. I want you to practice your abilities on the training bags in the pit below.\n\nThe bags are hung in groups of two. When I call out \"Left\", attack the bag on the left. When I call out \"Right\", attack the bag on the right.\n\nIf you fail to follow my simple directions, this task will become much harder.\n\nNow beat on those practice bags until they burst, {name}.", sourceObjective = "Destroy 2 Training Bags. Follow Instructor Xann's instructions to determine which bags to attack.", progress = "What are you waiting for?", completion = "You may not be a full-time trainee here, but do not let that keep you from learning anything.\n\nI can assure you, the ability to quickly switch targets will prove valuable in future fights.", sourceObjectiveStatus = "unverified-source-field" }
quests[29626] = { id = 29626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Groundskeeper Wu", description = "We don't have many rules here, but we do have one particular rule that is worth remembering. If you want to eat...\n\n<Xiao's stomach grumbles audibly.>\n\n...you have to work. Groundskeeper Wu can give you your chores for the day. He's in the market, to the west.", sourceObjective = "Report to Groundskeeper Wu at the Tian Monastery in the Jade Forest.", completion = "<Wu addresses you sharply.>\n\n{name}, is it? The High Elder's favored son? Yes, I remember you from the banquet.\n\nDon't expect any special treatment from me, boy. You'll be working just as hard as the greenest pandaren trainee here.\n\nPerhaps harder.", sourceObjectiveStatus = "unverified-source-field" }
quests[29627] = { id = 29627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Weapon", description = "First things first, though.\n\nA proper trainee needs a proper weapon. And a scrupulous trainee builds his own... or at least gathers the materials.\n\nThe switches which grow nearby should suffice for any respectable weapon. You'll also need to shop for black walnut extract to treat the wood. While you're there, get some ale, for...\n\n<Wu pauses.>\n\n...well, you know what ale is for.", sourceObjective = "Obtain 6 Rattan Switches from the area around the market in the Tian Monastery.\n\nPurchase a vial of Black Walnut Extract from June Whiteblossom.\n\nPurchase 3 Triple-Bittered Ales from Brewmaster Lei Kanglei.", progress = "<Wu looks at you expectantly.>", completion = "<Groundskeeper Wu gratefully scoops up the gathered materials.>\n\nI will have a weapon prepared for you by the end of your training. Now, onto the real work.", sourceObjectiveStatus = "unverified-source-field" }
quests[29628] = { id = 29628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strong Back", description = "Some of our trainees have... larger-than normal appetites. We have occasionally had difficulty supplying enough food for all of them. In times like these, we have to ask for help.\n\nA kindly older woman, who lives in a small house to the northwest, has agreed to make some stew for our trainees. All you need to do is go and get it.", sourceObjective = "Obtain a Boiling Cauldron from Mother Wu in the Waxwood Forest, then return to Groundskeeper Wu in the Tian Monastery.", progress = "She really is a nice woman. And an excellent cook.\n\nThe best cook in the world, actually.", completion = "I will see to it that this stew is distributed evenly and appropriately among the trainees.\n\nAfter I set some aside for myself, of course.", sourceObjectiveStatus = "unverified-source-field" }
quests[29629] = { id = 29629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Steady Hand", description = "The black walnut extract you purchased from Miss Whiteblossom is but one of many extracts we keep in stock for various applications.\n\nBlushleaf extract can be gathered from the flowers in the Waxwood Forest to the west. Several units can be extracted from one flower, but only those with calm nerves and steady hands can remove all of the extract from one flower.", sourceObjective = "Obtain 80 vials of Blushleaf Extract from Blushleaf Clusters in the Waxwood Forest.", progress = "It is said that the ancient herbalism masters were able to remove 20 vials of extract from each blossom.", completion = "Do not forget to wash your hands. Blushleaf stains forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[29630] = { id = 29630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And a Heavy Fist", description = "The greenwood sprites in the Waxwood Forest to the west pose no direct threat to us, this is true. However, their numbers have increased as of late, as have their wily antics.\n\nPart of our duty as wardens of this forest is to maintain the balance. Your duty is to do so by returning these sprites to the earth.", sourceObjective = "Slay 10 Greenwood Tricksters in the Waxwood Forest.", progress = "Very recently, I was walking in the Waxwood, when one of these sprites got on all fours behind my knees, evading my notice. Soon afterward, a second sprite approached me from the front, shoving me forcefully in the chest. Unaware of the first sprite, I stepped backwards, only to stumble on his prostrate form and fall, embarrassingly, onto my backside.\n\nSo yes, I have a vested interest in this assignment.", completion = "Thank you, {name}. The sprites' numbers will return in several days' time, but for now, the balance is maintained.", sourceObjectiveStatus = "unverified-source-field" }
quests[29631] = { id = 29631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Bright", description = "Might I ask a favor of you, trainee {name}?\n\nBefore I came to the monastery, I was a stranger to battle. During my time as a trainee, I performed adequately, but I was never placed in any real danger. Now, as a graduate and a wage-earning guard, I am expected to protect this perimeter at all costs.\n\nI can handle greenwood sprites, but the tigers in the western Waxwood are something different altogether. Would you mind taking care of them for me?", sourceObjective = "Slay 6 Waxwood tigers.", progress = "Please, do not speak of our arrangement with others. My cowardice shames me.", completion = "Thank you, {name}. A thousand times, thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29632] = { id = 29632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becoming Battle-Ready", description = "Alright, {race}. I'd like to see what you're really made of.\n\nYou'll find my pupils all over the monastery. Challenge them to fights. Push them to their limits. They have been instructed to do the same to you.\n\nWin or lose, you both will come out of the fight stronger.", sourceObjective = "Defeat 8 Tian Pupils in sparring matches at the Tian Monastery.", progress = "You may be a hero in your own lands, but here, you must prove your worth.", completion = "<Master Stone Fist eyes you warily.>\n\nAlright, I've seen enough. No more beating up on the younger pupils. We will proceed to the next phase.", sourceObjectiveStatus = "unverified-source-field" }
quests[29633] = { id = 29633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zhi-Zhi, the Dextrous", description = "Upon the hills to my right, you will find a hozen named Zhi-Zhi. He, too, won enough sparring matches to move up the ranks. I think he will provide you with more of a challenge.\n\nChallenge him, and try to defeat him.", sourceObjective = "Defeat Zhi-Zhi at the Tian Monastery.", progress = "Zhi-Zhi's style is different than that of most pandaren monks. He and his kind tend to have more... energy... than us.", completion = "It appears that I must move you up the ranks yet again, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29634] = { id = 29634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Husshun, the Wizened", description = "The jinyu are long-standing allies of the pandaren, and we welcome any of their kind into our monastery. Husshun, one of their elder shaman, is one of our newest trainees.\n\nHis skills as a monk are mediocre at best, but he is still a fierce combatant. He should provide you with the challenge that you deserve.", sourceObjective = "Challenge and defeat Husshun at the Tian Monastery.", progress = "I do not know why he decided to take the monastic path so late in life. It is not my place to ask. Such questions fall under the responsibility of our Spirit-Sage.", completion = "I must warn you, {class}:\n\nIf you continue defeating my best trainees, I will no longer be able to train you. And then you will have no excuse to enjoy the presence of my company.\n\nThink wisely before you quickly dispatch any more of my students.", sourceObjectiveStatus = "unverified-source-field" }
quests[29635] = { id = 29635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xiao, the Eater", description = "You may have already met my best student, Xiao, at the banquet tables. I personally would have graduated him several times over, but Instructor Xann insists that he needs more discipline.\n\nIf you ask me, discipline means very little if you win every fight you enter. I'm curious to see if Xiao can keep his streak alive against you.", sourceObjective = "Challenge and defeat Xiao at the Tian Monastery.", progress = "Young Xiao has a great future in martial arts. I wish you luck in your upcoming match.", completion = "I must admit, I was never surprised, {race}. You are a born fighter, and an excellent {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29636] = { id = 29636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Endurance", description = "I have taught you everything that I can, {name}. It is time you spoke with Instructor Myang.\n\nThe fights that she stages are less traditional than the sparring matches I am used to. Nevertheless, the path of a traveling adventurer like yourself is unpredictable, and a broad knowledge of fighting styles is an admirable trait.\n\nFarewell, {name}, and best of luck on the remainder of your training.", sourceObjective = "Report to Instructor Myang on the western side of the Tian Monastery.", completion = "Greetings, {name}. You are becoming quite famous among the trainees here. I have already heard your name whispered several times, usually between the puffy and discolored lips of one of your sparring partners.\n\nI'm looking forward to working with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29637] = { id = 29637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rumpus", description = "Master Stone Fist has trained you in the art of one-on-one combat. Now you learn the art of one-on-many.\n\nHow does fifty sound?\n\nLower yourself into the Ring of Inner Focus below, then, when you're ready, set off this firework. My assistants will come at you, several at a time.\n\nAll you need to do is survive.", sourceObjective = "Set off the Monastery Fireworks in the Ring of Inner Focus, then survive the Rumpus for two minutes.", progress = "Good luck, {name}.", completion = "Your {class} fighting style is strong, {name}. Our trainees could learn much from watching you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29639] = { id = 29639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flying Colors", description = "You have passed every test we prepared for you, {name}. It is now time for you to move on to bigger and better things.\n\n...but not before another banquet. The High Elder will be waiting for you at the banquet grounds to celebrate your graduation from our monastery.", sourceObjective = "Report to High Elder Cloudfall at the Tian Monastery in the Jade Forest.", completion = "Congratulations, {name}. While your traineeship was strictly honorary, your results were undeniably impressive. The young ones look up to you.\n\nGroundskeeper Wu had this prepared for you. Please, use it as you see fit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29640] = { id = 29640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Spy To'gun", description = "The Shadow Council has already killed most of our spies, but To'gun was foolish enough to escape only to go back in!\n\nYou must find him. He may be reckless, but we need to find out what he knows.", sourceObjective = "Locate Spy To'gun in the Shadow Labyrinth of Auchindoun.", completion = "Do you think you could help me get out of this cage?  It's a bit cramped.", sourceObjectiveStatus = "unverified-source-field" }
quests[29641] = { id = 29641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul Devices", description = "They've been torturing me, trying to get me to tell them everything that I know.\n\nThey fed the others to Hellmaw, and I was to be next. But I told them nothing!\n\nThey're using special devices to make their summoning more powerful. You must steal these devices!", sourceObjective = "Steal 5 Soul Devices and deliver them to Spy Grik'tha inside the Shadow Labyrinth of Auchindoun.", progress = "Were you able to find To'gun?", completion = "So, these are the soul devices that the Shadow Council were using to enhance their summoning power?  Intriguing.", sourceObjectiveStatus = "unverified-source-field" }
quests[29642] = { id = 29642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Auchindoun", description = "I have spies within Auchindoun and they have been sending me disturbing reports.  That place has been nothing but trouble ever since it exploded a couple of years ago.\n\nSomething in there has gone horribly wrong - again - and the Shadow Council is now on a war footing.  Though the reports were lacking on details, their preparations appear to be directed inward.\n\nYou must make your way to the Shadow Labyrinth.  My field commander, Mahfuun, will fill you in on what needs to be done.", sourceObjective = "Report to Field Commander Mahfuun inside the Shadow Labyrinth at Auchindoun in Terokkar Forest.", completion = "It's about time that you arrived.\n\nMehlisah said that she would be sending help days ago.  And we've been fighting in here longer than that!", sourceObjectiveStatus = "unverified-source-field" }
quests[29643] = { id = 29643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Codex of Blood", description = "Two years ago the Shadow Council summoned forth a being that shattered Auchindoun in its wake.\n\nRead the Codex of Blood to find out what happened. Be warned, Grandmaster Vorpil guards it with his life.", sourceObjective = "Read from the Codex of Blood in the Shadow Labyrinth of Auchindoun.", completion = "Opening the magically-suspended tome, a sense of dread overwhelms you.\n\nSomething is most definitely wrong here!", sourceObjectiveStatus = "unverified-source-field" }
quests[29644] = { id = 29644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Heart of the Labyrinth", description = "The Shadow Council has lost control of the cosmic being that they summoned here almost two years ago.\n\nKnown only as Murmur, it threatens to overrun the Shadow Council and break free into the outside world!", sourceObjective = "Destroy Murmur and inform Field Commander Mahfuun inside the Shadow Labyrinth of Auchindoun.", completion = "I cringe to think what would have happened had Murmur escaped to the outside world.\n\nThank you, brave hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[29645] = { id = 29645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambassador Hellmaw", description = "When the Cabal found our spies, they fed them to Ambassador Hellmaw one by one.\n\nOur men deserve justice. Slay the ritualists binding him, then dispose of Hellmaw.\n\nIt is a most deserving fate.", sourceObjective = "Kill 12 Cabal Ritualists and Ambassador Hellmaw, then return to Field Commander Mahfuun inside the Shadow Labyrinth of Auchindoun.", completion = "It won't bring anyone back, but at least justice has been done.", sourceObjectiveStatus = "unverified-source-field" }
quests[29646] = { id = 29646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flying Colors", description = "Well, I've done all that I can with you. Sounds like the others have, too.\n\nHigh Elder Cloudfall will be waiting at the banquet grounds, ready to celebrate your departure. Not that we're happy you're leaving... he just enjoys celebrations.", sourceObjective = "Report to High Elder Cloudfall at the Banquet Grounds in the Jade Forest.", completion = "Congratulations, {name}. While your traineeship was strictly honorary, your results were undeniably impressive. The young ones look up to you.\n\nGroundskeeper Wu had this prepared for you. Please, use it as you see fit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29647] = { id = 29647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flying Colors", description = "The Rumpus was your final test. You have mastered the disciplines taught at this monastery.\n\nJust as your training began with a banquet, so shall it end. High Elder Cloudfall should be waiting at the banquet grounds. I'll be right behind you.", sourceObjective = "Report to High Elder Cloudfall at the Banquet Grounds in the Jade Forest.", completion = "Congratulations, {name}. While your traineeship was strictly honorary, your results were undeniably impressive. The young ones look up to you.\n\nGroundskeeper Wu had this prepared for you. Please, use it as you see fit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29649] = { id = 29649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Save a Life", description = "Gunny is dying from a powerful curse, {name}.\n\nGrand Warlock Nethekurse augments his power with a pair of mystical braziers. If you bring me an ember from that brazier, perhaps it can counteract the dark magic?", sourceObjective = "Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel wants you to bring him a Fel Ember.", progress = "Did you bring the ember? We don't have much time!", completion = "He was a good soldier.", sourceObjectiveStatus = "unverified-source-field" }
quests[29650] = { id = 29650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Ember", description = "Caza'rez is dying a coward's death.\n\nGrand Warlock Netherkurse placed a terrible curse upon him. Perhaps if you were to bring me one of the embers from his braziers, we could use it to counteract the magic before it's too late?", sourceObjective = "Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel wants you to bring him a Fel Ember.", progress = "Did you bring the ember? Caza'rez deserves a warrior's death.", completion = "I will sing many songs of his glories.", sourceObjectiveStatus = "unverified-source-field" }
quests[29651] = { id = 29651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Dying", description = "Their elite warriors are ruthless... so... powerful.\n\n<Caza'rez spits up blood.>\n\nYou have to kill them... or we will never defeat Kargath...", sourceObjective = "Caza'rez inside the Shattered Halls of Hellfire Citadel wants you to kill 4 Shattered Hand Legionnaires, 2 Shattered Hand Centurions, and 2 Shattered Hand Champions.", progress = "Are they dead, {class}?", completion = "Caza'rez...is no more.", sourceObjectiveStatus = "unverified-source-field" }
quests[29652] = { id = 29652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Favor", description = "Ol' Gunny doesn't have much longer...\n\nDo me one last favor, and kill the biggest, meanest fel orcs ye can find.\n\nFor old times' sake, aye?", sourceObjective = "Gunny inside the Shattered Halls of Hellfire Citadel wants you to kill 4 Shattered Hand Legionnaires, 2 Shattered Hand Centurions, and 2 Shattered Hand Champions.", progress = "Did ye kill 'em?", completion = "If only we could have saved him.", sourceObjectiveStatus = "unverified-source-field" }
quests[29653] = { id = 29653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Will of the Warchief", description = "Kargath was once one of the Horde's greatest heroes.\n\nHe now wears the false mantle of Warchief. Bring me his namesake weapon so that we can remember the champion he once was, rather than the monster he's become.", sourceObjective = "Bring Warchief Kargath's Fist to Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel.", progress = "Have you proof of Kargath Bladefist's defeat?", completion = "We should not forget the orc Kargath once was, nor the lessons to be learned from his downfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[29654] = { id = 29654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning the Tide", description = "There is only one true way to end the fel orc threat to Honor Hold and the Alliance.\n\nTheir Warchief must be slain.\n\nBring me his namesake weapon, so that we can always remember his death.", sourceObjective = "Bring Warchief Kargath's Fist to Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel.", progress = "Have you returned with proof of 'Warchief' Kargath Bladefist's demise?", completion = "We have struck a major blow against the enemy with your help.\n\nHonor Hold is far safer than it's been in years.", sourceObjectiveStatus = "unverified-source-field" }
quests[29655] = { id = 29655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Very Special Cloth", description = "Warbringer O'mrogg has killed more brave soldiers than any enemy I've ever encountered. He is ruthless, cunning, and extremely powerful.\n\nTake him down and bring me his warcloth so that we may fashion it into a banner and show them the fury of the Horde!", sourceObjective = "Kill Warbringer O'mrogg and bring his warcloth to Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel.", progress = "Did you bring me the cloth?", completion = "Well done. This will show those blood crazed monsters what they're up against.", sourceObjectiveStatus = "unverified-source-field" }
quests[29656] = { id = 29656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O'mrogg's Warcloth", description = "Stormwind wants to see proof of our successes in the war effort.\n\nRather than showing him body bags, I thought we'd present him the warcloth of O'mrogg, Kargath's fiercest warrior. Think you can handle him?", sourceObjective = "Kill Warbringer O'mrogg and bring his warcloth to Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel.", progress = "Did you bring me the cloth?", completion = "My superiors will be very pleased to see this. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29657] = { id = 29657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With Great Power, Comes Great Responsibility", description = "<A voice like the sound of light bells rings in your head.>\n\nThe Mechanar employs my race's technology to create manacells, objects which provide great amounts of power.\n\nI need you to eliminate Mechano-Lord Capacitus so that Kael'thas' forces cannot harvest that power.", sourceObjective = "A'dal has asked you to slay Mechano-Lord Capacitus in the Mechanar of Tempest Keep.", completion = "You have done well, {name}. But more work remains to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[29658] = { id = 29658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Calculator", description = "<A gentle wind caresses your face.>\n\nOne more task yet remains.\n\nPathaleon the Calculator oversees many of his master's operations. He is personally responsible for much of the recent torment that has plagued this world.\n\nI ask that you eliminate him.", sourceObjective = "A'dal has asked you to slay Pathaleon the Calculator in the Mechanar of Tempest Keep.", completion = "You have my gratitude, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29659] = { id = 29659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Treasure", description = "I sense that one of my kind's artifacts has been taken and stashed away in the Cache of the Legion.\n\nWe cannot give them time to discover its power. If you would kill the Gatewatchers and retrieve it for me, I would be most grateful.", sourceObjective = "Retrieve the Blinding Fury for A'dal from the Cache of the Legion in the Mechanar of Tempest Keep.", sourceObjectiveStatus = "unverified-source-field" }
quests[29660] = { id = 29660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Botanica", description = "Kael'thas' forces in the Botanica were unsuccessful in handling the numerous creatures contained within. We must take action to right their wrongs.\n\nThe first step is to eliminate their forces so that they cannot cause further problems.", sourceObjective = "A'dal wants you to kill Commander Sarannis, High Botanist Freywinn, and Thorngrin the Tender inside the Botanica of Tempest Keep.", completion = "They were going to die to the creatures contained here soon even without our interference. It is for the greater good.", sourceObjectiveStatus = "unverified-source-field" }
quests[29661] = { id = 29661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of Dry Fur", description = "Through meditation, I intend to find a route to locating Shu. In the meantime, you would benefit from practice and discipline.\n\nYour first task is the task of all trainees entering the pools: cross the balance poles to the west and ring the bell without falling into the pool.\n\nShould you fall, the pool's curse will make it difficult to get on a pole again, so you will need to return to the edge of the pool to start over.\n\nOh, and beware the cranes.", sourceObjective = "Cross the balance poles and ring the training bell.", completion = "Good. You're a quick study.", sourceObjectiveStatus = "unverified-source-field" }
quests[29662] = { id = 29662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stronger Than Reeds", description = "Gather me reeds from the nearby pools.\n\nDo not question why. Do, and then observe the results.", sourceObjective = "Gather 8 Hard Tearwood Reeds.", progress = "Telling you of my strength means nothing. I must show you.", completion = "Good.\n\nNo number of reeds have ever withstood my might.\n\nStep back, and let me dispel your doubts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29663] = { id = 29663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Balanced Rock", description = "I require peace to perform my meditation. Practice your arts while I meditate on Shu's location.\n\nOther monks practice balance and combat upon the balance poles in the surrounding pools. Engage them and defeat them.", sourceObjective = "Defeat 6 Tushui Monks atop the balance poles.", completion = "Even now, your skills increase. Your footing becomes more sure. Your blows strike with more force.\n\nDiscipline and practice are the keys to reaching our full potential.", sourceObjectiveStatus = "unverified-source-field" }
quests[29664] = { id = 29664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Fires", description = "You're strong of mind and strong of will, but you lack the skills to face me in combat. You must fight with your body, but in truth, it is your character that is being tested.\n\nLet us even the playing field.\n\nTake this torch, light it in the brazier next to me, and then use it to light the three unlit braziers around the pool.", sourceObjective = "Light your Unlit Challenger's Torch at the Brazier of Flickering Flame, then use it to light the 3 braziers near Master Li Fei.", progress = "You are not yet ready to face me. First, you must light the braziers.", completion = "These fires will give you the strength that you've not yet obtained. They will illuminate your potential.", sourceObjectiveStatus = "unverified-source-field" }
quests[29665] = { id = 29665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Bad to Worse", description = "After their ship crashed, evil creatures swept up from the sea to pick through the wreckage. Our aid may seem but a drop in the pond at the thought of the misfortune they've faced today.\n\nDefeat their tormentors. These people desperately need our help.", sourceObjective = "Defeat 8 Deepscale Tormentors.", completion = "You are a fear to behold upon the battlefield.", sourceObjectiveStatus = "unverified-source-field" }
quests[29666] = { id = 29666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sting of Learning", description = "There are dangers in the pools. The latest and most vicious are the water pincers. A time has come for their numbers to be diminished, and I am no longer up to the task.\n\nIf you could clear out some of the water pincers, I would be very appreciative. Beware their numbers... sometimes it's best to lure them from the pool-side rather than wading all the way in.", sourceObjective = "Kill 6 Water Pincers.", completion = "The water pincers are strange creatures. They seem to be drawn to still water.", sourceObjectiveStatus = "unverified-source-field" }
quests[29667] = { id = 29667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Herd", description = "It seems that Kael'thas' forces have twisted the Botanica's specimens beyond saving. I do not want to see them unleashed upon Outland as so many others have.\n\nThere is one, Laj, who I would like to examine. He is different somehow. Perhaps we can learn from him.", sourceObjective = "A'dal has asked you to kill 6 Mutate Fleshlashers, 6 Mutate Fear-shriekers, 6 Mutate Horrors, and to obtain a Rapidly Evolving Frond from Laj in the Botanica of Tempest Keep.", progress = "I see you have obtained the frond. Very good.", completion = "You have done well thus far, {name}. However, there is still one more task I must ask that you complete.", sourceObjectiveStatus = "unverified-source-field" }
quests[29669] = { id = 29669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Somber Task", description = "I must now ask you to complete a most somber task.\n\nWarp Splinter used to act as guardian to all of the Botanica. He is now impure, and must be taken down.", sourceObjective = "A'dal has asked you to slay Warp Splinter in the Botanica of Tempest Keep.", completion = "He was a noble guardian in life. His presence will be missed.", sourceObjectiveStatus = "unverified-source-field" }
quests[29670] = { id = 29670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maul Gormal", description = "Thanks to you, there's a small militia of farmers hiding nearby. Hanae said something about giving them \"liquid courage\" which, I'm pretty sure, means they're sauced and ANGRY.\n\nThe mogu think they can walk all over us - we'll give them a fight that will open their eyes.\n\nFollow the trail through the ruins and down to the beach. Find their leader. When you engage him, we'll be there to back you up.", sourceObjective = "Kill Subjugator Gormal in Camp Gormal.", progress = "We are ready to fight the mogu leader whenever you are.", completion = "This is extremely unsettling. If mogu are banding together like this all over the continent, it could become a major threat to Pandaria.", sourceObjectiveStatus = "unverified-source-field" }
quests[29674] = { id = 29674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbound Darkness", description = "<The sound of chimes enters your head, but it is distressed.>\n\nWe imprisoned the most dangerous beings we came across in our travels.\n\nZereketh is a powerful void lord. If he escapes into Netherstorm, he will feed off of the abundant void energy.", sourceObjective = "A'dal has asked you to slay Zereketh the Unbound in the Arcatraz of Tempest Keep.", completion = "Creatures of the void are naturally chaotic. They are a necessary part of the universe, but they must be kept in check by the Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[29675] = { id = 29675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hey There Dalliah", description = "Two powerful agents of the Burning Legion, Wrath-Scryer Soccothrates and Dalliah the Doomsayer, have begun rallying the demons on board together into a small army.\n\nYou cannot let their forces grow any larger, or the Arcatraz may soon become yet another Legion stronghold.", sourceObjective = "A'dal has asked you to kill Wrath-Scryer Soccothrates and Dalliah the Doomsayer in the Arcatraz of Tempest Keep.", completion = "The Legion seeks only to consume. They hold no regard for the balance.", sourceObjectiveStatus = "unverified-source-field" }
quests[29676] = { id = 29676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding an Old Friend", description = "It seems Shu, the spirit of water, had a play companion when he came to the pools throughout the years. An old pandaren we know as Old Man Liang.\n\nLiang moved away from the main town and stopped practicing in the pools some time ago. I am told he lives in a small house northeast of here, up the hill.\n\nLiang may know what has driven Shu away, and where the spirit might be found.\n\nGo to Liang. Ask of Shu.", sourceObjective = "Speak to Old Man Liang at Liang's Retreat in the Singing Pools.", completion = "Visitors are rare up here, but you are welcome. It is nice to meet you, young {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29677] = { id = 29677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sun Pearl", description = "Shu, the spirit of water, is eternally young, as are all the spirits of Shen-zin Su. I have been friends with Shu all of my life, but I no longer have it within me to play with him. I am old, and lack the energy.\n\nFor all his complexities, Shu is simple to please: he desires friendship. When I returned to play with Shu each season, I would always bring a Sun Pearl as a gift, and then we would play together. You can find a Sun Pearl in the pools to the southeast. Perhaps you can be his new friend.", sourceObjective = "Retrieve the Sun Pearl.", progress = "The decision to not return to the pools was a hard one. I don't think Shu ever truly understood. He does not know what it is to get older and weaker.", completion = "Shu's desires are not so different from our own. He does not want to be alone. Unwanted, unloved. He longs to be needed, and to share his life with others.\n\nKnowing that, earning his trust is not terribly difficult. He just wants company.", sourceObjectiveStatus = "unverified-source-field" }
quests[29678] = { id = 29678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shu, the Spirit of Water", description = "Shu, the spirit of water, is sulking in the deep pool to the north. Cross the rocks and then drop the sun pearl in the center of the pool. He will know what this means.", sourceObjective = "Coax Shu, the spirit of water, into a game.", sourceObjectiveStatus = "unverified-source-field" }
quests[29679] = { id = 29679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Friend", description = "He wants you to play with him. Go for it!", sourceObjective = "Water walk into 5 of Shu's Water Spouts.", completion = "I have to admit, that looked pretty fun from my angle.\n\nAnd you seem to have made a new friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[29680] = { id = 29680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Source of Our Livelihood", description = "We have done as Master Shang asked of us. I will return to the temple to inform the master of our progress. You should continue south on the road to the farmlands to seek out Wugou, the spirit of earth.\n\nJi awaits you at the Dai-Lo Farmstead, and he'll surely need your help. I must warn you, Ji can be reckless in his directness. Remember well the things I have taught you: discipline and patience.", sourceObjective = "Speak to Ji at the Dai-Lo Farmstead. A cart is waiting near the road to take you there.", completion = "{name}! I wondered when I would see you again!\n\nWell, the plus side is that finding Wugou, the spirit of earth, was easy enough. Waking him... not so much. I think he's going to wake quite sore from all the pushing and hitting I've done trying to rouse him.", sourceObjectiveStatus = "unverified-source-field" }
quests[29681] = { id = 29681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maximum Security Breakout", description = "Harbinger Skyriss is the heart of the problem in the Arcatraz.\n\nHe corrupted Warden Mellichar and made him release many of the prisoners. It is only a matter of time before the Harbinger himself is let loose.\n\n{name}, you cannot let a servant of the Old Gods live!", sourceObjective = "A'dal has asked you to slay Harbinger Skyriss in the Arcatraz of Tempest Keep.", completion = "Thank you, {name}. Your actions this day have prevented countless tragedies.", sourceObjectiveStatus = "unverified-source-field" }
quests[29682] = { id = 29682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magisters' Terrace", description = "We recently sent in an expeditionary force to the Magisters' Terrace to stop the Legion forces there.\n\nHowever, we haven't heard from them since, and I fear the worst.\n\nWill you go there and try to find Exarch Larethor? He's in charge of the expedition.", sourceObjective = "Captain Theris Dawnhearth wants you to find Exarch Larethor inside the Magisters' Terrace.", completion = "Dawnhearth thought we were dead? Hah!\n\nI haven't sent a report because we haven't made any progress past this point.\n\nPerhaps you can help us change that?", sourceObjectiveStatus = "unverified-source-field" }
quests[29684] = { id = 29684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Severed Communications", description = "We've had a contact embedded in Magisters' Terrace gathering intelligence for us for some time now, but we've lost contact with him.\n\nThe information he was collecting is vital to our mission.", sourceObjective = "Exarch Larethor inside the Magisters' Terrace wants you to find Tyrith, a blood elf spy.", completion = "...Come closer, {race}... Listen carefully to my words....", sourceObjectiveStatus = "unverified-source-field" }
quests[29685] = { id = 29685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard to Kill", description = "As you've now witnessed, the Legion forces work tirelessly, manipulating the Sunwell's power to achieve their malevolent ends.\n\nKael'thas has risen from the ashes of defeat and once more leads them in their efforts. He must be stopped.", sourceObjective = "Kalecgos has asked you to defeat Kael'thas in Magisters' Terrace. You are to take Kael's head and report back to Larethor inside the Magisters' Terrace.", progress = "Well, {class}, I must admit, I wasn't sure I'd see you again.", completion = "<Larethor listens intently as you explain your deeds in Magisters' Terrace.>\n\nTyrith will be missed - good man, that one. Thanks to you though, his death wasn't in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[29686] = { id = 29686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Radical Notion", description = "We cannot afford to lose this war. I'd like to empower our sentries so that brave men and women don't have to die.\n\nThe Legion has gotten a hold of a powerful elemental being. Its essence could be just what we need.", sourceObjective = "Exarch Larethor in the Magisters' Terrace wants you to kill Vexallus and obtain its essence.", progress = "Were you able to get your hands on its essence?", completion = "Excellent! I can't wait to present this project to my superiors!", sourceObjectiveStatus = "unverified-source-field" }
quests[29687] = { id = 29687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Associations", description = "The Legion and Kael'thas' forces are becoming increasingly intertwined. This concerns me very deeply.\n\nFrom what we can gather Selin Fireheart and Priestess Delrissa work closely together to unite the two armies. You need to stop them.", sourceObjective = "Exarch Larethor in the Magisters' Terrace wants you to kill Selin Fireheart and Priestess Delrissa.", completion = "Well done, soldier. One step at a time.", sourceObjectiveStatus = "unverified-source-field" }
quests[29688] = { id = 29688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advancing the Campaign", description = "I mostly listen, {class}. I listen so that the Warchief doesn't have to.\n\nI've heard of the status of our campaign against the Hellfire Citadel. It is time to take the Shattered Halls, seat of power for the fel orcs.\n\nGo speak with Stone Guard Stok'ton, he's in charge there.", sourceObjective = "Shadow Hunter Ty'jin has asked you to speak with Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel.", completion = "Keep your head down, or it's likely to end up on the wrong end of an arrow.", sourceObjectiveStatus = "unverified-source-field" }
quests[29689] = { id = 29689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advancing the Campaign", description = "The time has come to lay the final blow against the fel orcs.\n\nAdvance Scout Chadwick awaits your presence inside the Shattered Halls of Hellfire Citadel. Make haste, their forces could strike against Honor Hold at any moment!", sourceObjective = "Force Commander Danath Trollbane has asked you to speak with Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel.", completion = "Be quiet! We'll surely be overwhelmed if they notice us now.", sourceObjectiveStatus = "unverified-source-field" }
quests[29690] = { id = 29690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Mists", description = "<Nazgrim fills his lungs with sea air.>\n\nYou smell that, {name}? It's the smell of our home, the lands our kind have bled and died to preserve.\n\nAnd listen... you hear that? It's the sound of peace and safety - a haven we've carved, where our enemies fear to tread.\n\nRemember these things. You won't experience them again anytime soon. We have ourselves a war to win.\n\nNow go get settled, we're shovin' off!", sourceObjective = "Speak to General Nazgrim on Hellscream's Fist.", completion = "{name}!?\n\nThey told me you were dead...\n\nI'm glad to see it wasn't true. There's Alliance to kill!", sourceObjectiveStatus = "unverified-source-field" }
quests[29691] = { id = 29691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me A Shrubbery!", description = "My people use sanguine hibiscus for a number of purposes.\n\nIt grows naturally only in the Underbog, and many of the bog's denizens have taken a liking to it.\n\nIf you could bring me some, I would be very grateful.", sourceObjective = "Collect 5 Sanguine Hibiscus and return them to T'shu in the Underbog.", progress = "Were you able to gather any hibiscus?", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?", sourceObjectiveStatus = "unverified-source-field" }
quests[29692] = { id = 29692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me Another Shrubbery!", progress = "We can still use more sanguine hibiscus. We're always struggling to find more.\n\nBring them to me in bunches of five and I will be most grateful.", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?" }
quests[29693] = { id = 29693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The General's Edge", description = "As you gradually gather your senses and begin to take in your surroundings, this object stands out amongst the strewn wreckage.\n\nIt occurs to you that this is the first time you've seen Nazgrim's axe outside of his tight grasp. Somehow, this fact makes your predicament even more unsettling...\n\nYou know that dead or alive, the General would want his weapon back in his possession.", sourceObjective = "Bring Nazgrim's axe to General Nazgrim.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[29694] = { id = 29694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regroup!", description = "They have an airbase! I have underestimated this Alliance Captain for the last time. So many good warriors lost...\n\nThere must have been a few survivors who were able to bail during the crash. We need every able-bodied fighter we can get.\n\nFind as many survivors as you can in the forest below, and I will investigate the wreckage itself. Rally everyone together at the nearby village for a counter-attack.", sourceObjective = "Rescue Shademaster Kiryn, Rivett Clutchpop, Shokia, and Sergeant Gorrok from Honeydew Glade.", progress = "Did you find any survivors?", completion = "These are the only survivors, {name}?\n\nSo be it. We will play the hand fate has dealt us.\n\n\n\nNumbers be damned. This is where heroes are made.", sourceObjectiveStatus = "unverified-source-field" }
quests[29696] = { id = 29696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Stars!", description = "A number of Kiryn's articles have been scattered around the area by wood sprites, but this one stands out as important to you.\n\nThe bag once hung from her waist, loaded with throwing stars. Without them, her arsenal will be considerably diminished.\n\nIf you were to retrieve the weapons from the pests that inhabit this region, it could only help your cause.", sourceObjective = "Collect 100 of Kiryn's Throwing Stars from Devious Wood Sprites.", sourceObjectiveStatus = "unverified-source-field" }
quests[29703] = { id = 29703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrel of Monkies", description = "These monkeymen are driving me insane!  I was just trying to get some insight into panderan brewing tactics and these hozu things keep drinking the brews before I can properly chemical test them.  Can you please go take a few of them out as a lesson to the others?  I'll make it worth your while.", sourceObjective = "Sally Fizzlefury wants you to kill 5 drunken monkies.", sourceObjectiveStatus = "unverified-source-field" }
quests[29715] = { id = 29715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Witch in the Woods", description = "Oh please {race}!  Can you help me?\n\nSome of the village children were playing in the woods and haven't come back. Could you please keep an eye out for them if you are going out there?\n\nI told those village rascals to leave that old widow up in the woods alone. My guess is they are probably harassing her. They think she is a witch.", sourceObjective = "Find An Windfur on the road north of the Jade Witch Hut.", sourceObjectiveStatus = "unverified-source-field" }
quests[29716] = { id = 29716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Double Hozen Dare", description = "There is a witch in the woods but no one believes me. She turned my friend Shin into jade!\n\nWe were all so scared we tried to run back but she sicced her big jade monsters on us. A bunch of my friends tried to get away by climbing trees.\n\nCan you help me save my friends?", sourceObjective = "Rescue 6 Scared Pandaren cubs.", progress = "Where is Shin? I didn't see Shin.", completion = "Oh thank you so much for helping find my friends.  I still don't see Shin though...", sourceObjectiveStatus = "unverified-source-field" }
quests[29717] = { id = 29717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down Kitty!", description = "I tried to fight one of the jade tigers in the woods but they were too scary. They stare at you and you turn to a jade statue!\n\nHonest truth! Chen's sister's friend Ni heard it from Kai's mom.\n\nI want to be brave like you though. Can you show me how to beat up those jade tigers?", sourceObjective = "Destroy 8 Jade Guardians.", progress = "Wow! You are tough!", completion = "Wow! You were awesome! You were like *bam* and they were like *aaaaa* and then they were smashed!", sourceObjectiveStatus = "unverified-source-field" }
quests[29722] = { id = 29722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Bravery", description = "Can you help teach me to be brave like you?\n\nWhen we played our prank on the witch we made a bunch of Leafy Tricksters angry.  I think the witch did something to them.\n\nCan you show me how you stand up to them?", sourceObjective = "Defeat 8 Leafy Tricksters south of the Jade Witch Hut.", sourceObjectiveStatus = "unverified-source-field" }
quests[29723] = { id = 29723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jade Witch", description = "The Jade Witch must still have Shin.\n\nI... I can't do it! I don't want to see the witch. Can you please go talk to her and see if she has Shin?\n\nYou're an adult, I don't think she would try to turn you into jade.", sourceObjective = "Defeat the Jade Witch.", completion = "Hurray! Thank you so much! Shin is saved and you beat up the old witch! And the best part is our parents were never told what we were up to. Hurray!\n\nIt looks like everybody who came back are trying to get rid of whatever jade they had. Toya's been collecting it for some reason and said you should go chat with him.", sourceObjectiveStatus = "unverified-source-field" }
quests[29725] = { id = 29725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Report: Fire From the Sky", description = "Yeah, we found Amber, she's alive, and all that. That's about where the good news stops though.\n\nLet's see if I can pick up where ol' Rell left off...", sourceObjective = "Listen to Sully's report.", progress = "I'm not done with the report yet, {name}. Settle down.", completion = "So, now you know why ol' Rell's all beat up.\n\n<You detect a change in Sully's facial expression, and he quickly turns away. Is he... crying?>", sourceObjectiveStatus = "unverified-source-field" }
quests[29726] = { id = 29726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Report: Hostile Natives", description = "I... I can tell you what happened next! We continued north, into the forest...", sourceObjective = "Listen to Little Lu's report.", completion = "Luckily, we all made it out alive.\n\nWell... all of us except for Socks...", sourceObjectiveStatus = "unverified-source-field" }
quests[29727] = { id = 29727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Report: Take No Prisoners", description = "The final leg of our journey took us west, to a large hozen village. We set up a small camp in the mountains, outside of their line of sight...", sourceObjective = "Listen to Amber Kearnen's report.", progress = "Please, allow me to finish.", completion = "So there you have it. We didn't find the White Pawn, but we came back with intel that could be of even greater importance to the Alliance.\n\nThe Horde have allied with the hozen, and are arming them as we speak. They and their monkey army now outnumber us thirty to one.", sourceObjectiveStatus = "unverified-source-field" }
quests[29728] = { id = 29728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Evidence", description = "I must ask you to do one more thing for me, {name}.\n\nThe personal effects on this ship cannot be left for others to find. We'll have to destroy it.\n\nI cobbled together some Makeshift Dynamite from the scraps you brought me.\n\nPlace the dynamite anywhere on the ship, but take care not to put them too close together.\n\nThey might be...uh...a little unwieldy, so you should spread them out in case of premature detonation.", sourceObjective = "Plant 4 Makeshift Dynamite near the sunken ship at Sapphire's End. Makeshift Dynamite must be placed at least 10 yards apart.", sourceObjectiveStatus = "unverified-source-field" }
quests[29730] = { id = 29730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Report: Hostile Natives", description = "I bet I know your first question: \"What the ook happened to Sergeant Gorrok?\" Don't worry, don't worry. He's totally alive. Not dead or anything.\n\n<Riko shuffles uncomfortably.>\n\nWell, we THINK he's alive, but he ALSO might be very, very dead.\n\n<Riko looks into your eyes for approval.>\n\nFine! Let me tell you exactly what happened.", sourceObjective = "Listen to Riko's report.", completion = "So, as you can see, none of this is Riko's fault.", sourceObjectiveStatus = "unverified-source-field" }
quests[29731] = { id = 29731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Report: On the Right Track", description = "MOST of what Riko said is true.\n\nWe didn't dare pursue Gorrok - the Horde's numbers here are far too few. Our forces can only sustain so many losses, and frankly, we don't know how powerful that witch really is.\n\nLet me pick up where the hozen left off...", sourceObjective = "Listen to Kiryn's report.", progress = "If I may continue, please?", completion = "And that's how we found our Alliance captive.\n\nBut that's not all that happened. Not by a long shot...", sourceObjectiveStatus = "unverified-source-field" }
quests[29732] = { id = 29732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Goes Down, Must Come Up!", description = "Rivett left behind what looks to be an important piece of equipment. Along its shaft you are able to make out the words: Goblin Drone Dispenser.\n\nWith a simple calibration, the device is set to deliver drones to Nazgrim's basecamp.\n\nEasy enough....\n\nThere's just one problem. The only supply crates worth transporting have fallen to the cliff ledge below the crash impact.\n\nAs you ponder the issue, you see the long, coiled tail of a Cliff Glider fly by the corner of your eye...", sourceObjective = "Use the Goblin Drone Dispenser near the Exposed Root to recover supplies.\n\nNOTE: Each use will require one Cliff Glider Tail.", sourceObjectiveStatus = "unverified-source-field" }
quests[29733] = { id = 29733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Report: Lost in the Woods", description = "<Rell coughs heavily before speaking.>\n\nPlease, {name}. You need to hear what we've been through.\n\nThe whole damned Alliance needs to hear what we've been through. There may not be much time left.", sourceObjective = "Listen to Rell's report.", progress = "<Rell doesn't look too good. He should probably save his energy.>", completion = "...and that's <cough> how we found...\n\n<Rell's speech devolves into heavy coughing. The corner of his mouth produces a trickle of blood.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29734] = { id = 29734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deepforge the Elder", sourceObjective = "Your spirit burns with life, young {class}.  I accept the homage you pay, and offer in return this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[29735] = { id = 29735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonebrand the Elder", sourceObjective = "Your spirit burns with life, young {class}.  I accept the homage you pay, and offer in return this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[29736] = { id = 29736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkfeather the Elder", sourceObjective = "Your spirit burns with life, young {class}.  I accept the homage you pay, and offer in return this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[29737] = { id = 29737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firebeard the Elder", sourceObjective = "Your spirit burns with life, young {class}.  I accept the homage you pay, and offer in return this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[29738] = { id = 29738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonlance the Elder", sourceObjective = "The heavens, in their countless stars, hold answers to earthly mysteries, {name}.  Might, then, the wise, and the lucky, gaze up and find truth?", sourceObjectiveStatus = "unverified-source-field" }
quests[29739] = { id = 29739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windsong the Elder", sourceObjective = "The heavens, in their countless stars, hold answers to earthly mysteries, {name}.  Might, then, the wise, and the lucky, gaze up and find truth?", sourceObjectiveStatus = "unverified-source-field" }
quests[29740] = { id = 29740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evershade the Elder", sourceObjective = "The heavens, in their countless stars, hold answers to earthly mysteries, {name}.  Might, then, the wise, and the lucky, gaze up and find truth?", sourceObjectiveStatus = "unverified-source-field" }
quests[29741] = { id = 29741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sekhemi the Elder", sourceObjective = "All tol'vir were once as I am. Now, my people are flesh and blood, and more in need of the wisdom of the ages than ever before.", sourceObjectiveStatus = "unverified-source-field" }
quests[29742] = { id = 29742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menkhaf the Elder", sourceObjective = "All tol'vir were once as I am. Now, my people are flesh and blood, and more in need of the wisdom of the ages than ever before.", sourceObjectiveStatus = "unverified-source-field" }
quests[29743] = { id = 29743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monstrosity", description = "It's plain to see that this statue and the surrounding ruins are of ancient origin. Clearly, this land has a deep history, which means it could not have been born of the cataclysm.\n\nAnd yet these waters have been explored for ages now, with no record of anything here but open sea.\n\nPerhaps if you were to sketch the pieces of this broken statue, you might shed light on the continent's origins.", sourceObjective = "Collect sketches of each piece of the ancient statue.", sourceObjectiveStatus = "unverified-source-field" }
quests[29744] = { id = 29744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some \"Pupil of Nature\"", description = "Wood sprites are not prone to wandering, so I'm surprised they ventured down as far as the mason's quarter. Something must be forcing them out of their natural habitat.\n\nThese particular sprites are native to the Woods of the Lost, just north of here. I'd go myself, but I've heard those woods are haunted.\n\nSo yeah, that's out.\n\nI guess we'll never know.\n\n<Weng coughs.>\n\nOrrrr... A big brave adventurer like YOU could go check it out! What do you say?", sourceObjective = "Investigate the Woods of the Lost, northeast of the Greenstone Quarry.", sourceObjectiveStatus = "unverified-source-field" }
quests[29745] = { id = 29745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sprites' Plight", description = "<Living statues rampage through the woods.\n\nFor now, they seem content in pummeling the forest sprites into splinters, but if they continue any further the pandaren will have more than just missing jade to worry about.>", sourceObjective = "Slay 10 Stonebound Destroyer the Woods of the Lost and discover their source.", sourceObjectiveStatus = "unverified-source-field" }
quests[29747] = { id = 29747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break the Cycle", description = "<Mogu conjurers call forth hapless spirits from beyond, forcing them into statues.\n\nIt seems that destroying the statues alone will not be enough to break the cycle.>", sourceObjective = "Kill 8 Shan'ze Spiritbinders in the Terrace of Ten Thunders.", sourceObjectiveStatus = "unverified-source-field" }
quests[29748] = { id = 29748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simulacrumble", description = "<The shattered remains of an ancient mogu statue. This one looks like it never animated before it was broken.\n\nWhatever dark magic the mogu are employing here, it seems to make the brittle statues significantly tougher. Better to destroy them while they are still vacant.\n\nA good old-fashioned kick should do the job.>", sourceObjective = "Kick 6 Vacant Destroyers in the Terrace of Ten Thunders.", sourceObjectiveStatus = "unverified-source-field" }
quests[29749] = { id = 29749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Urgent Plea", description = "<Your mind is racked with a howl. Beneath it, a wispy voice is barely audible, as if from far away.>\n\nPlease... help... heart of the ruins... a ritual... conjuring...\n\n...should not be here...\n\nMy staff... on the altar... take it. Please hurry.", sourceObjective = "Recover the Staff of Pei-Zhi and interrupt the mogu ritual in the center of the Terrace of Ten Thunders.", progress = "Spirit-binding! How can the mogu have been allowed to resume such a disgusting practice?! And now here I am, the product of a half-failed conjuring...\n\n<The spirit fumes for a moment, then turns to you.>\n\nWhat century is this?", completion = "Allow me to introduce myself: I am Pei-Zhi, Master Spiritsage under the last pandaren emperor Shaohao.\n\nAt least... I was.", sourceObjectiveStatus = "unverified-source-field" }
quests[29750] = { id = 29750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vessels of the Spirit", description = "The Spiritclaws are a sect of mogu assassin-priests who, at the height of the mogu empire, were the most elite and most feared of the emperor's troops.\n\nAll have mastered a deathblow which ensnares the spirit of the enemy, trapping it in a jade bottle for delivery to a Spiritbinder.\n\nIf you encounter any Spiritclaws further ahead in the ruins, take note: their belts hang with a cursed weight.\n\nRelieve them of their burden and bring the bottles back to me.", sourceObjective = "Recover 8 Spirit Bottles from Shan'ze Spiritclaws in the Terrace of Ten Thunders.", progress = "To think the mogu have continued training the Spiritclaws for all these years...\n\nDid you get the bottles?", completion = "Thank you, {class}.\n\nI can already sense the spirits within these bottles - they cry out with fear, confusion... rage.", sourceObjectiveStatus = "unverified-source-field" }
quests[29751] = { id = 29751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Artifacts", description = "So many spirits held in captivity here... I can feel them everywhere. Even the walls are a cage for the long-dead.\n\n{name}, we cannot simply break the sorcery over this place - doing so would release countless agonized souls to wander the earth. They will need a beacon, something to guide them.\n\nWith your help, I can create a tan-chao: a bridge from this world to the heavens. For this ritual, I'll need a bowl, a candle, and a jade cong. You should be able to find them all within the ruins.", sourceObjective = "Bring Pei-Zhi a Chipped Ritual Bowl, a Pungent Ritual Candle, and a Jade Cong from the Terrace of Ten Thunders.", progress = "Have you found the items we need for the ritual? We cannot guide these spirits back without them.", completion = "Good work. With these, I can complete the ritual to send all of the spirits here--including myself--back where they belong.", sourceObjectiveStatus = "unverified-source-field" }
quests[29752] = { id = 29752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wayward Dead", description = "The process of mass conjuring, as the mogu are doing here, is not without byproduct. Some spirits arrive too distraught or unruly to be harnessed, so they are confined and left to wander until their desperation leaves them more malleable.\n\nI suspect the mogu have such a holding area somewhere nearby, likely guarded by spiritclaws.\n\nPlease, take my staff again and use it to collect these wayward spirits. You needn't fight them - present the staff and they should be drawn in.", sourceObjective = "Use the Staff of Pei-Zhi to absorb 10 Wayward Ancestors in the Terrace of Ten Thunders.", progress = "We mustn't forsake the wayward dead.", completion = "Thank you, {name}. I will take them with me into the nether.", sourceObjectiveStatus = "unverified-source-field" }
quests[29753] = { id = 29753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Nature", description = "I'm afraid I have another favor to ask, {name}.\n\nThe bottles you recovered contain neither the spirits of mogu ancestors nor recently slain foes; they contain spirits of beasts. It seems the spiritclaws have resorted to poaching in an effort to fuel their simulacra.\n\nThis complicates our task, for I cannot take the beasts with me through the bridge.\n\nTake the bottles west to Tideview Thicket and smash them to return the spirits to nature. Some may be blind with rage and will need to be subdued.", sourceObjective = "Throw Spirit Bottles on the ground in Tideview Thicket to release 8 Beast Spirits.", progress = "Do not fear for the spirits of the beasts - they will find peace here.", completion = "Their bodies had long since returned to the land - their spirits can now follow.", sourceObjectiveStatus = "unverified-source-field" }
quests[29754] = { id = 29754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Bridge Earth and Sky", description = "We are ready to open the tan-chao and guide all of these spirits back to peace.\n\nIf I may, I would have your assistance once more. The mogu will surely sense the ritual taking place and will do everything in their power to halt it. I need only a few moments without interference, and once the path is open it will surge too greatly to be closed.\n\nIf you are willing to help one more time, please accompany me to the ritual site.", sourceObjective = "Protect Pei-Zhi during his ritual at the Terrace of Ten Thunders.", sourceObjectiveStatus = "unverified-source-field" }
quests[29755] = { id = 29755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pei-Back", description = "<Ancestral spirits stream into the tan-chao, Pei-Zhi's bridge to freedom.\n\nOne final chamber lingers in the ruins, just north of the tan-chao. The air above crackles with foul energy. Shan Jitong is already at work.>", sourceObjective = "Confront Shan Jitong and rescue Pei-Zhi at the Seat of the Spirit Waker in the Terrace of Ten Thunders.", completion = "This age must be one of great strife to breed heroes such as you. I can only imagine what adventures must lie ahead.\n\nIt has been my great honor to have met you, {name}.\n\nI will remain here to usher out the last of the spirits before crossing the tan-chao myself.\n\nStill, I am disturbed by the spirit waker's dying curse...\n\n\"You will not stop the thunder.\"\n\nWhat could he have meant?", sourceObjectiveStatus = "unverified-source-field" }
quests[29756] = { id = 29756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Humble Offering", description = "I'm almost ready for the ritual, there's just one more thing we need: An offering.\n\nRelax, I don't mean a sacrifice. Just a bit of food.\n\nThere are sure to be mushrooms growing in Tideview Thicket to the northwest that are suitable for this. Please bring some.", sourceObjective = "Gather 10 Tidemist Caps from Tideview Thicket.", progress = "Even the dead know hunger.", completion = "Thank you, {name}. These mushrooms may not seem like much of an offering, but the sentiment alone will be enough to draw the spirits to us.\n\nAlso, they make a pretty fine stir-fry.", sourceObjectiveStatus = "unverified-source-field" }
quests[29757] = { id = 29757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bottletoads", description = "Have you heard about the crisis we're having at the pools?\n\nToads have moved in and are spawning like crazy! It's become a real problem for the lotus farmers.\n\nCoincidentally, I make a jam out of gelatinous toadspawn. I call it \"Bottletoads\" and it's a big hit with the kids around here. Can't keep any in stock.\n\nIf you're heading to the pools, you'd be doing everyone a favor by uh... liberating some of those toad eggs.\n\nInto this bottle. For me.\n\nJust look for bubbles and scoop right in!", sourceObjective = "Scoop toad eggs from 8 Gurgling Toadspawn on the top level of the Pools of Purity.", progress = "\"It just ain't a party without Bottletoads!\"\n\nHmm... no, that doesn't work.\n\n\"Bottletoads: not as gross as they sound!\"", completion = "Now when the kids ask: \"Do you have Bottletoads?\" I can say YES!", sourceObjectiveStatus = "unverified-source-field" }
quests[29758] = { id = 29758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guess Whose Back", description = "<This dragon turtle's massive shell is rock-hard and covered in sharp ridges. One of the locals could almost certainly make use of it.>", sourceObjective = "Bring Krosh's Back to Yan in New Cifera.\n\nProvided item:", completion = "My MY now look at THIS! What a beautiful shell!\n\nYou were wise to bring this to me, my friend. It will make a fantastic serving platter.\n\nPlease, take this for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[29759] = { id = 29759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kung Din", description = "I hope you are capable of this next task, for our lives depend on it.\n\nThere is only one key that will unlock our chains. Unfortunately, the key hangs around the neck of the hozen's pet tiger, Kung Din.\n\nThey keep the tiger in the great pit to the north. The only way to retrieve the key will be to kill the beast.", sourceObjective = "Obtain the Slingtail Key by slaying Kung Din.", progress = "Did you find him?", completion = "Yes, with this key I will be able to free our chains.\n\nYou have delivered us from this vile place.", sourceObjectiveStatus = "unverified-source-field" }
quests[29760] = { id = 29760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pit Fighter", description = "There must be more to being a master pit fighter than this...\n\nPerhaps Korgol Crushskull who runs the Darkmoon Deathmatch at the Faire will know.", sourceObjective = "Speak with Korgol Crushskull at the Darkmoon Faire.\n\nProvided item:", completion = "Well met, {class}.\n\nGaining but one trinket is not enough to make you a Master Pit Fighter.\n\nNow is the time to truly prove your steel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29761] = { id = 29761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master Pit Fighter", progress = "Well met again, {class}.\n\nBring me 12 trinkets of the Pit Fighter and then you shall be a Master Pit Fighter of the Darkmoon Deathmatch!", completion = "Many foes have you bested and many crowds entertained.\n\nI am glad to name you Master Pit Fighter of the Darkmoon Deathmatch!" }
quests[29762] = { id = 29762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Family Heirlooms", description = "We recently lost a fierce battle against the hozen at Moonwater Retreat.\n\nWe evacuated as many of our people as we could, but still, there were many we could not save.\n\nWe have no tokens of our lost over which to send our prayers.\n\nIf someone could go and retrieve heirlooms from the dead bodies, we could properly lay them to rest, and move on.\n\nIt would mean so much to us if you could do this, {name}.", sourceObjective = "Collect 8 Pearlfin Heirlooms from dead Pearlfin Villagers in Moonwater Retreat.", progress = "We still grieve for our fallen brothers.", completion = "Thank you, {name}. You do not know how much this means to the families of the lost.", sourceObjectiveStatus = "unverified-source-field" }
quests[29763] = { id = 29763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Their Thunder", description = "The vrykul are fearless in a fight. Seems they actually yearn fer a death in battle. With their numbers and that ferocity, we're doomed - plain and simple.\n\nThere's one they esteem though, goes by the name of Ingvar. Bring him down and you'll deal a mighty blow to their spirit.", sourceObjective = "Defender Mordun has asked you to acquire the head of Ingvar the Plunderer.", progress = "Good to see you're well, {name}.\n\nWe've had about as many casualties as we can handle.", completion = "Outstanding!\n\nThis could be the turn of luck we've all been hoping for.", sourceObjectiveStatus = "unverified-source-field" }
quests[29764] = { id = 29764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarmament", description = "Take it from me, <lad/lass>, them vrykul weapons be downright nasty! Deceptively well-balanced, wickedly sharp - just plain deadly.\n\nI need you to pilfer some o' them weapons before they're used on us!", sourceObjective = "Defender Mordun wants you to steal 5 Vrykul Weapons", progress = "You pinch a load a' them vrykul axes?", completion = "<Mordun whistles.>\n\nWill ya just look at 'em? Incredible.\n\nI half expected these neanderthals to be swingin' around clubs and throwin' rock.\n\nNo such luck...", sourceObjectiveStatus = "unverified-source-field" }
quests[29765] = { id = 29765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cryin' My Eyes Out", description = "I coulda taken out da whole lot of 'em, mon.\n\nShot 'em one by one, den played dead when dey be gettin' close. Fell for it every time, dey did - well almost every time...\n\nOne of 'em finally got wise. Called my bluff. Before I knew it, dey was usin' my eyes as marbles.\n\nRan off with my goods an' left me here ta die, da savages...\n\nHelp me, mon. Lemme die wit my dignity intact.", sourceObjective = "Collect Zin'Jun's belongings from the Hozen Groundpounders.\n\nIf you lose Zin'Jun, speak to him at the Ascent of Swirling Winds.", progress = "You got me goods, mon?", completion = "<Zin'Jun sobs...you think.>\n\nDey done killed Snuff...\n\nWhat'd 'ol Snuff ever do ta dem?", sourceObjectiveStatus = "unverified-source-field" }
quests[29766] = { id = 29766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Good Start", description = "Regardless of our predicament, our orders stand. We are to learn the lay of this land and prepare it for Hellscream's fleet.\n\nBut first, we must deal with these savages!\n\nYou see these corpses I've stacked up around the camp? I want mountains of them!\n\nWe are the Horde!\n\nThese vermin have not learned to fear us yet, but we will fix that soon enough...", sourceObjective = "Kill 4 Hozen Mudflingers, 4 Hozen Skullthumpers, and 3 Hozen Fishcatchers", sourceObjectiveStatus = "unverified-source-field" }
quests[29767] = { id = 29767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Fry", description = "Fortune favors the bold!\n\nYour calculated aggressive actions have yielded unexpected rewards. If you can slay these fishcatchers after a successful haul, you'll inherit their slippery spoils.\n\nThinning out the enemy while feeding your allies - the picture of efficiency!", sourceObjective = "Collect 12 Mature Carp from Hozu Fishcatchers", sourceObjectiveStatus = "unverified-source-field" }
quests[29768] = { id = 29768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Mallet", description = "{name}, I've got it! It's simple really. Let's make a ruckus so loud that there's no way he can sleep through it.\n\nWhy look at that, a conveniently placed gong! Makes me think this may just be how they've awoken him in the past. We just need the matching mallet to get it ringing as loud as possible.\n\nThe village leader tells me the mallet is over at the Ki-Han Brewery on the river, to the southwest. It's not far. Mind picking it up for me while I give the village some fair warning?", sourceObjective = "Recover the Dai-Lo Recess Mallet at the Ki-Han Brewery.", progress = "Well, they're as warned as they're going to get. Do you have the mallet?", completion = "Hah, {name}! Now that's a mallet if I've ever seen one! Let's make some noise.", sourceObjectiveStatus = "unverified-source-field" }
quests[29769] = { id = 29769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rascals", description = "I'll keep trying to find ways to wake this stubborn little guy up, but there is no shortage of trouble on the island it seems. The crops to the south are infested with virmen, rabbit-like thieves and pillagers.\n\nRascals!\n\nThey breed faster than we can kill them! I have the perfect solution for such a situation: kill them faster! With you here, {name}, that shouldn't be a problem.", sourceObjective = "Kill 10 Virmen.", completion = "{name}, that's the way to do it! You show up, and problems start getting solved. That's just one of many reasons why I like you!", sourceObjectiveStatus = "unverified-source-field" }
quests[29770] = { id = 29770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Good!", description = "The virmen to the south have been running off with all of our crops, but they're taking more than they can eat. They must be stockpiling them somewhere - the ones they like anyway.\n\nWill you go out and recover any of the uprooted crops you can find? I've got an island's worth of people to feed, and every single vegetable makes a difference.", sourceObjective = "Recover 3 Uprooted Turnips, 3 Stolen Carrots, and 3 Pilfered Pumpkins.", progress = "Ever since Wugou. the spirit of earth, fell asleep, the dirt is drying out and it's getting harder and harder to get new seeds to sprout. We need to hold on to any food we can, or the island will have hard times ahead.", completion = "Some of these have mouth-sized chunks bitten out of them! Ah well, we can still make use.\n\nThank you for your help, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[29771] = { id = 29771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stronger Than Wood", description = "Gather me wood planks from construction near the Ki-Han Brewery.\n\nYou do not yet know the extent of my strength, so I shall display it to you.", sourceObjective = "Gather 12 Discarded Wood Planks.", progress = "Have you done as I've asked?", completion = "Good.\n\nMy head, it is harder than the densest wood.\n\nStep back, and let me dispel your doubts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29772] = { id = 29772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raucous Rousing", description = "You ready for this, {name}? I'm thinking maybe we should have looked for something to cover our ears, but it's a bit late for that now. Just remember that the intense ringing you'll be hearing for the next few hours is the ringing sound of victory!\n\nThe honor's all yours, {name}. Ring the gong whenever you're ready!", sourceObjective = "Ring the gong.", completion = "Huh... well... that's definitely the ringing I expected, but I was hoping for a bit more from Wugou. This guy's a deep sleeper, that's for sure.\n\nIt's alright, {name}. I've got another idea, and there's not much preparation needed at all - just how I like it.", sourceObjectiveStatus = "unverified-source-field" }
quests[29774] = { id = 29774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not In the Face!", description = "Alright {name}, I was thinking about what we'd try next if the whole gong thing didn't work, and it came to me just like that! Water in the face always worked on me. It's got to be twice as effective for someone so dry and earthy!\n\nMind going over and asking Shu, the spirit of water, if he'll help us out?  He should be playing in the pool next to the waterfall, just on the other side of that tree.", sourceObjective = "Request Shu's help in waking Wugou, the spirit of earth.", completion = "YEAH!!! {name}, we make quite a team. Persistence over planning, I always say!", sourceObjectiveStatus = "unverified-source-field" }
quests[29775] = { id = 29775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirit and Body of Shen-zin Su", description = "Well, that wraps it up here, doesn't it {name}?  Now that we've got these two roused and all friendly towards you, we just need to get them back to the Temple of Five Dawns.\n\nYou go ahead. I'm going to say my goodbyes, then I'll follow you up shortly.", sourceObjective = "Bring Shu and Wugou, the spirits of water and earth, to the Temple of Five Dawns. A cart is waiting near the road to take you there.", completion = "You have done well, young student. Three of the four spirits have been returned to the temple. We are closer to the answers we seek.", sourceObjectiveStatus = "unverified-source-field" }
quests[29776] = { id = 29776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morning Breeze Village", description = "The fourth and final spirit is Dafeng, the spirit of air. When he is not in the skies, he can be found on the Ridge of Laughing Winds to the west. I've sent both Aysa and Ji to help you find him.\n\nWhen you are ready, I will summon winds to carry you to the top of the temple. From there, cross the bridges to the west and find Ji in Morning Breeze Village.", sourceObjective = "Meet with Ji Firepaw in Morning Breeze Village.", completion = "{name}, give me a hug! Our parting was not so long this time - I quite prefer it that way!\n\nYou've been working with Aysa, have you not? Our disciplines have always kept us apart, so I know little of her. Watching her perform her exercises now, I must confess that she possesses a grace and discipline that is strangely alluring.\n\nThere are more pressing thoughts though, aren't there? {name}, let's take care of this monkey problem while we search for Dafeng.", sourceObjectiveStatus = "unverified-source-field" }
quests[29777] = { id = 29777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools of the Enemy", description = "The hozen have stolen our brushes and are painting over our scrolls of wisdom with their own wisdoms, if you can call them that. If you're here to help, stop them and bring our brushes back before they can do more harm.", sourceObjective = "Retrieve 8 Paint Soaked Brushes.", progress = "I do not wish to disparage the hozen for their aspirations - each race must walk its own path. In this moment, however, they are bringing harm to our bodies and our culture. That is a line that cannot be crossed.", completion = "I am very thankful, young one. I will soon begin the slow task of documenting all of our wisdoms again, so that the scrolls can be hung for the benefit of all to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[29778] = { id = 29778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rewritten Wisdoms", description = "{name}, we must help Elder Shaopai. There are few more deserving of our kindness.\n\nOn the way here, you surely noticed the scrolls of wisdom hanging in the grotto to the south. The hozen have defiled many of them, and sadly, they are not recoverable. We will deal with the problem directly - burn the defiled scrolls. Wipe the hozen writings away entirely.\n\nDo not worry for Elder Shaopai. The people shall come together and help him rewrite the wisdoms in time. I shall see to that.", sourceObjective = "Burn 5 Defaced Scroll of Wisdom.", completion = "You're a good man, {name}. You have proven that again and again, and I am glad to stand beside you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29779] = { id = 29779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Direct Solution", description = "Alright {name}, this is the second time we've had to deal with ravaging hozen. I think it's time we take care of this problem the Huojin way. No more patience. No more mediation. We go to the source.\n\nWe're going into the hozen village to the north and we're punishing those smelly troublemakers. I've been looking forward to a chance to fight by your side again, {name}.", sourceObjective = "Kill 20 hozen in Fe-Feng Village.", progress = "The time for kindness is done. We have monkeys to kill.", completion = "Invigorating! A good fight always makes me feel better!", sourceObjectiveStatus = "unverified-source-field" }
quests[29780] = { id = 29780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do No Evil", description = "{name}, I need you to understand that the way of the Huojin is not the way of violence. When fighting is needed, we will not hesitate, but when fighting is not needed, neither do we instigate. However, the direct solution is often cutting the head off the snake, as they say.\n\nThe hozen have a leader instigating these attacks. If we remove Ruk-Ruk, we won't have to wipe the hozen out entirely.\n\nI know you are not of the Huojin, but are you with me in what must be done, {name}?", sourceObjective = "Kill Ruk-ruk, the Fe-Feng Chief.", completion = "{name}, I think you've got a bit of Huojin in you. Stick with me and I'll bring you around, I think.", sourceObjectiveStatus = "unverified-source-field" }
quests[29781] = { id = 29781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monkey Advisory Warning", description = "The monkeys have been stealing from the village during their attacks. We should be fine without some of the extra food stores, but the idea of monkeys with fireworks... I'm a little bit concerned. Not to mention, who knows when some fireworks will come in handy?\n\nHelp me recover the stolen fireworks from their village, {name}?", sourceObjective = "Recover 8 Stolen Firework Bundles.", progress = "I'm somewhat impressed they hadn't set their village on fire with these things.", completion = "{name}, I'm thinking we should celebrate with these later. What do you think?", sourceObjectiveStatus = "unverified-source-field" }
quests[29782] = { id = 29782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stronger Than Bone", description = "This giant jade tiger pillar doesn't seem to fit in amidst the hozen buildings.\n\nWhat it does seem is very hard. Very solid.\n\nYou know just the person to bring this to.", sourceObjective = "Bring the Jade Tiger Pillar to Jojo Ironbrow in Morning Breeze Village.\n\nProvided item:", completion = "GOOD! A true challenge. Let us put this pillar to the test!", sourceObjectiveStatus = "unverified-source-field" }
quests[29783] = { id = 29783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stronger Than Stone", description = "Gather me stone blocks from the Ridge of Laughing Winds to the south.\n\nYou have seen my strength twice, yet I still spy doubt within your eyes. It will not last.", sourceObjective = "Gather 12 Abandoned Stone Blocks.", progress = "The strength of the body cannot exist without the strength of the mind.", completion = "Good.\n\nMy head, it is harder than the strongest stone.\n\nStep back, and let me dispel your doubts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29784] = { id = 29784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balanced Perspective", description = "Aysa has been meditating on the lake since we've arrived, all her thoughts focused on Dafeng. I don't know what she hopes to discover out there, but she's no fool, and Master Shang Xi has entrusted this task with her.\n\nYou will need to cross the ropes leading from the end of the dock to reach her. It shall test your balance, but I think you're up to the task, {name}.", sourceObjective = "Cross the ropes and speak to Aysa Cloudsinger on Morning Breeze Lake.", completion = "I'm impressed. Most students that are even capable of reaching this spot do so soaking wet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29785] = { id = 29785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dafeng, the Spirit of Air", description = "If you listen long enough, the wind will carry the answer to you.\n\nDafeng, the spirit of air, has been scared from the skies by Zhao-Ren, the Onyx Serpent. He hides within the Chamber of Whispers, at the south side of the plateau.\n\nGo to him. Ji and I will join you there.", sourceObjective = "Speak to Dafeng, the spirit of air, in the Chamber of Whispers.", completion = "Dafeng looks frightened as you approach, but settles a bit at the sound of your voice.", sourceObjectiveStatus = "unverified-source-field" }
quests[29786] = { id = 29786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for the Skies", description = "Dafeng, the spirit of air, is terrified by Zhao-Ren, the Onyx Serpent. We must help him face that fear, or face it for him ourselves.\n\nWhen I told Ji of the serpent, he said he had an idea and would begin preparations outside of the chamber. Despite his rash nature, I must admit, I envy his passion and conviction.\n\nLet us go outside and confront the Onyx Serpent.", sourceObjective = "Defeat Zhao-Ren, the Onyx Serpent with the aid of Ji's fireworks.", completion = "You have helped Dafeng, the spirit of air, find his courage! The final spirit has been restored.", sourceObjectiveStatus = "unverified-source-field" }
quests[29787] = { id = 29787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worthy of Passing", description = "The four elemental spirits will help you speak with the land and uncover its plight, but first, I have one small task to ask of you.\n\nJoin me, my pupil. Accompany this old pandaren to the western grove.", sourceObjective = "Defeat the Guardian of the Elders.", completion = "I do not have the strength of body or will that I once did. I'm glad there are noble {race} like you to fight on for our people. You've come far, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29788] = { id = 29788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Nature", description = "You faced forest sprites in the Dawning Valley, but the forest sprites in this grove are a different breed. Crueler and more dangerous.\n\nIf you would clear some of these sprites out, the spirits would thank you.", sourceObjective = "Kill 8 Thornbranch Scamps.", completion = "The spirits thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29789] = { id = 29789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small, But Significant", description = "I am tired, {name}. I must rest.\n\nWe have a ritual to perform, but we require some of the charms from this grove. If you wander the grove, you should see them all over hanging from the trees. \n\nIf it does not offend one as young as you, will you permit me to sit and recover my strength while you gather these charms?", sourceObjective = "Retrieve 8 Kun-Pai Ritual Charms.", progress = "Rest feels good. The burdens of life have become a great weight after so many years.", completion = "You come through, as you always have. You are truly one of my greatest students. I think you will be something the likes of which the world has never seen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29790] = { id = 29790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passing Wisdom", description = "This journey shall soon be yours to undertake without me. Stay for a few moments and listen to an old man's words. Let my knowledge serve as a foundation for yours, that you might be greater than I ever was.", sourceObjective = "Listen to Master Shang Xi.", completion = "I know, {name}... I know. Such is the way of things.", sourceObjectiveStatus = "unverified-source-field" }
quests[29791] = { id = 29791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Suffering of Shen-zin Su", description = "Now is not the time to grieve. The balloon is ready, and Shen-zin Su awaits.\n\nWe shall be the first pandaren to speak to Shen-zin Su in hundreds of years. It is a great honor.", sourceObjective = "Board the Hot Air Balloon and Speak to Shen-zin Su.", completion = "You have undergone a great honor, {class}. Have you come back wiser for it?", sourceObjectiveStatus = "unverified-source-field" }
quests[29792] = { id = 29792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bidden to Greatness", description = "It is up to all of you to remove the thorn from the side of Shen-zin Su. Do not let your differences come between you. Trust in each other.\n\nWithin the Pei-Wu Forest is a lone hermit. Head directly to his hut. He knows intimately of the dark things that now lurk in the trees.", sourceObjective = "Open the gates to Pei-Wu Forest.", completion = "Evil is rising from the seas and filling the forest. It's not just tigers anymore... something far more sinister lurks in the shadows, waiting to take any {race} unwise enough to stray out alone.\n\nYou are not safe here.", sourceObjectiveStatus = "unverified-source-field" }
quests[29793] = { id = 29793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evil from the Seas", description = "I do not know what this evil is that is infesting the forest, {name}, but I know exactly how to deal with it. So do you, I think.", sourceObjective = "Kill 8 Darkened Horrors or Darkened Terrors.", completion = "You make me proud, {name}. You make all of us proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[29794] = { id = 29794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "None Left Behind", description = "Your friend has been doing everything she can to save my crew. I'm deeply appreciative.\n\nWe're still dealing with more than we can handle here: quenching the fires on the wreckage, getting my people out, fighting off these evil sea creatures, and trying to prevent the prisoners from escaping. We're simply in over our heads.\n\nI still have men on the ship that we need to get clear before the wreckage collapses on them. I know this is asking a lot, but can you help?", sourceObjective = "Rescue 3 Injured Sailors.", completion = "I have no idea who you people are, but fate surely smiled on us this day. Many more would be dead if not for the help of you and your friends. I am in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29795] = { id = 29795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking Stalks", description = "My men are malnourished, injured, and exhausted, but they are Horde. Every one will fight to their dying breath. As our new ally, we will stand by you when the time comes, but we would stand stronger with weapons.\n\nI have my men out gathering bamboo stalks to fashion into spears. If you can spare the effort, we could use the extra pair of capable hands.", sourceObjective = "Gather 10 Broken Bamboo Stalks.", progress = "The Horde does not back down from a fight.", completion = "These are excellent! We'll have them crafted into weapons in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[29796] = { id = 29796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgent News", description = "I'm sure Aysa won't love this plan, but it's the only plan we've got. Would you mind being the bearer of bad news for me, {name}? She needs to know what we're doing so she can get everyone to safety.", sourceObjective = "Speak to Delora Lionheart at the Wreck of the Skyseeker.", completion = "Your friend is out fighting to save my crew. Fiercely I might add. I'm afraid your message may have to wait.", sourceObjectiveStatus = "unverified-source-field" }
quests[29797] = { id = 29797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medical Supplies", description = "We need supplies to tend to our wounded, but the supply crates containing them were scattered in the crash. If you can bring back any crates you find, I would be very grateful.", sourceObjective = "Recover 8 Crates of Medical Supplies.", progress = "Did you find the boxes I spoke of?", completion = "These will do perfectly. I'll get my medics to work immediately.\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29798] = { id = 29798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Evil", description = "{name}, I was looking for you!\n\nOne of the escaping sailors just spotted Aysa in the wreckage of the ship, facing some enormous beast. She might need your help - you should go to her, quickly!", sourceObjective = "Defeat the Vordraka, the Deep Sea Nightmare.", completion = "<Aysa is clearly exhausted from the fight.>\n\nYour skills in battle... are unquestionable... {class}.\n\n\n\nDid you save the escaped prisoners?  ...Where is Ji? Is he okay?", sourceObjectiveStatus = "unverified-source-field" }
quests[29799] = { id = 29799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Healing of Shen-zin Su", description = "This is more horrific than I imagined, but we can handle this. We need to gather the healers and close the wound. We need to save Shen-zin Su.\n\nFind any healers you can! Rescue them, relieve them - whatever you need to do to get them over here healing the wound.\n\nKeep the healers safe at all costs!", sourceObjective = "Rescue and defend healers until Shen-zin Su's wound is healed.", completion = "You are a sight to see when under pressure, {name}! We wouldn't have stood a chance without you.\n\nI think it's working. The flow of blood is slowing. I knew it would work!", sourceObjectiveStatus = "unverified-source-field" }
quests[29800] = { id = 29800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Allies", description = "{name}, I did what had to be done. And the plan worked. Things could have been much worse had we not acted. I only wish Aysa could understand that.\n\nThere will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.", sourceObjective = "Return to the Temple of Five Dawns. A cart is waiting near the Wreck of the Skyseeker to take you there.", completion = "It is good to see you again, {name}. You've done all that I've asked of you and more... you have saved Shen-zin Su.\n\nYou make an old master proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[29801] = { id = 29801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Your Worth", description = "Hello, {name}! You've earned a reputation among the flight as having - shall we say - 'nimble fingers.'\n\nWe need someone of your skills for a matter of utmost delicacy. Before I reveal more, we need to know you're the right <man/woman> for the job.\n\nWhen the course of battle takes you to the Eye of Eternity, I need you to pickpocket Hagara the Stormbinder to retrieve a cryptomancer's decoder ring. Are you up to the task?", sourceObjective = "Pickpocket a cryptomancer's decoder ring from Hagara the Stormbinder at the Eye of Eternity within the Dragon Soul raid encounter.", progress = "Have you completed our task?\n\nThese artifacts are crafted such that they dissolve if their bearer is killed, so only a skilled thief can acquire them.", completion = "You've found one! You're a credit to your race, {name}.\n\nRings like these are capable of decoding even the most complicated of ciphers. Unfortunately, the ring is inert until it is charged...", sourceObjectiveStatus = "unverified-source-field" }
quests[29802] = { id = 29802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hidden Message", description = "Corastrasza, currently stationed at the Vermillion Redoubt in the Twilight Highlands, has intercepted a coded message of grave importance. I'll let her explain the full situation, but we need your expertise to unravel the cipher!\n\nTake your decoder ring to an ethereal thaumaturge in your capital city - he should know how to charge it. Acquire the encoded cipher from Corastrasza and use the ring to decode it for her. Hurry! Time is ticking...", sourceObjective = "Charge your Cryptomancer's Decoder Ring and use it to decode the Corastrasza's Singed Cipher.", progress = "I was hoping Lord Devrestrasz would find us a competent {class}.\n\nWhat have you got for us, {name}? Do you have a means of decrypting the message?", completion = "What's this about? \"Ravenholdt Manor?\" I thought that was just a motley band of thieves up in the Hillsbrad Foothills.\n\nWhat would they want with a dragon egg? More importantly, how did they find out about it?\n\nWe're going to need some answers, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29803] = { id = 29803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ears of the Lich King", description = "Prince Keleseth acts as Arthas' eyes and ears in the Fjord.\n\nI don't like that one bit!\n\nGo and give him a round o' pain. You'll be doing the world a favor by doing so.", sourceObjective = "Defender Mordun inside Utgarde Keep wants you to slay Prince Keleseth.", progress = "It is good to see you again, {name}.", completion = "I bet the pale whelp felt that!\n\nThat's one more step towards yer judgment day, Arthas!", sourceObjectiveStatus = "unverified-source-field" }
quests[29804] = { id = 29804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seein' Red", description = "I was just about ta curl up an' die, mon.\n\nNow, dis!\n\nSnuff an' me go way back. Oh, da memories...\n\nNo way I can face Snuff in da afterlife without avengin' his death first, mon!\n\nDese hooligans be led by one named Konk. We gotta sniff him out an' den snuff him out - for Snuff!", sourceObjective = "Kill Konk.", completion = "Zin'jun is lost?\n\nThis is a dark day indeed, brother. These vermin will pay!", sourceObjectiveStatus = "unverified-source-field" }
quests[29806] = { id = 29806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wanderer", sourceObjective = "Defeat the Roaming Brawler in a fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[29807] = { id = 29807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Traitor King", description = "Anub'arak, the traitor king, makes his home in the once proud Kingdom of Azjol-Nerub.\n\nHe has twisted and perverted our homeland into the wretched squalor it is today. He rules over an army of undead nerubians who have pledged themselves to serving the Lich King.\n\nBring an end to his reign.", sourceObjective = "Reclaimer A'zak in Azjol-Nerub has tasked you with defeating Anub'arak. You are to return to A'zak with Anub'arak's Broken Husk.", progress = "Is it done, {class}? Has the traitor king finally met his end?", completion = "<A fierce glow emanantes from all of Azak's eyes as he stares at the husk.>\n\nIt is DONE!\n\nYour name shall be recorded in the extensive history of our people, {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29808] = { id = 29808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Forget the Eggs!", description = "Throughout Azjol-Nerub, the scourged nerubians carefully nurture eggs that will soon hatch, providing them nerubian young to slaughter and raise.\n\nThe eggs have been tainted with foul magics. Our only recourse is to dispose of them.", sourceObjective = "Reclaimer A'zak in Azjol-Nerub wants you to destroy 6 Nerubian Scourge Eggs.", completion = "Do not worry, {race}.\n\nThe eggs they found were but a fraction of our hidden stores within Azjol-Nerub.\n\nOur mighty kingdom shall be reborn.", sourceObjectiveStatus = "unverified-source-field" }
quests[29809] = { id = 29809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Efficient Excavations", description = "This manual describes outlandish theories on how to most efficiently manage large groups of workers as they engage in massive excavation projects.\n\nAfter a quick skim of the material, it becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here.\n\nA map on the back cover indicates that the author has a bunker in the southwest region of Uldum.\n\nPerhaps an introduction is in order.", sourceObjective = "Bring 'Efficient Excavations' to Belloc Brightblade in Schnottz's Landing.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[29811] = { id = 29811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gatewatcher's Talisman", description = "Krik'thir, guardian of the gates to Azjol-Nerub, was not a traitor.\n\nHe fell in the War of the Spider defending our home from the Scourge.\n\nAs per his station, he was in possession of the key to the hidden empire. I'd like you to retrieve it so it may be returned to its people.", sourceObjective = "Reclaimer A'zak in Azjol-Nerub wants you to retrieve the Gatewatcher's Talisman from Krik'thir the Gatewatcher.", progress = "Has Krik'thir's spirit been released from the curse of undeath? What of the talisman?", completion = "Just as I suspected.\n\nMost of the empire has remained closed off since Krik'thir's final stand. Perhaps my people have already secured the depths and merely await release? Perhaps the faceless ones fester behind closed doors.\n\nOnly time will tell. The exposed upper reaches of Azjol-Nerub must first be cleansed of Arthas' taint.", sourceObjectiveStatus = "unverified-source-field" }
quests[29815] = { id = 29815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forensic Science", description = "These creatures are everywhere - and very hostile! We'll need to deal with them before any more Alliance show up.\n\nThis one's taken quite a beating, but I've still made some determinations about its anatomy.\n\nWith the proper reagents, I'll be able to fashion a poison that should be quite effective against this species. In fact, I'll just need to modify a bit of the poison I have with me.\n\nGo and find me some viscous chlorophyll down by the water. Any semi-sentient flora should do.", sourceObjective = "Collect 8 Viscous Chlorophyll.", progress = "I hope you were successful. Our survival here may depend on it.", completion = "Oh, yes, {name}. This will do nicely.", sourceObjectiveStatus = "unverified-source-field" }
quests[29820] = { id = 29820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Nexus", description = "I sent Warmage Kaitlyn into the Nexus to investigate the chaos that is Malygos' domain, but she hasn't reported back in days.\n\nWould you mind going there and lending her aid? I'm certain she could use help if she hasn't been eaten by dragons.", sourceObjective = "Archmage Berinand has asked you to speak with Warmage Kaitlyn in the Nexus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29821] = { id = 29821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missed Me By... That Much!", description = "Listen, <pal/toots>.\n\nI sent out a coupla supply drones from the gunship, and they've all been lost or crashed. Almost all, that is.\n\nOne of 'em buzzed right through the camp here and crashed out by them waterfalls.\n\nHow 'bout you see what you can do about bringin' the contents of that crate back here, hmm?\n\nWe're all outta drones, but my rocket boots might yet come in handy... or footy, as the case may be.\n\nHah! I just kill me...", sourceObjective = "Find the missing supply crate at Serenity Falls.\n\nProvided item:", completion = "This crate should be full of supplies...", sourceObjectiveStatus = "unverified-source-field" }
quests[29822] = { id = 29822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lay of the Land", description = "Curse these furry pests! Kill one, and two more rise in its place...\n\nNothing has changed, {name}. Orders are orders, no matter how few of us stand and regardless of the odds.\n\nI have plans to make and problems to solve.\n\nI want you to get out there and learn the lay of the land. Don't return until you have something useful to report.\n\nAnd silence that yammering fool while you're out there!\n\nDismissed!", sourceObjective = "Visit the Shrine of the Sun, the Shrine of the Moon, and Kill Dook Ookem.", completion = "Welcome, traveler.\n\nPlease, make yourself comfortable.", sourceObjectiveStatus = "unverified-source-field" }
quests[29823] = { id = 29823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Report: The Friend of My Enemy", description = "We weren't only looking for Alliance, you know. We were also looking for those snooked-up, tik-flikklin' jinyu!\n\nWell, we found 'em all right...", sourceObjective = "Listen to Riko's report.", progress = "Riko wishes you were a bit more patient, {name}.", completion = "Yeah, I ran away. So blikkin' what? If it weren't for me, Kiryn would be dead. Oh, wait... she's already dead... already...\n\nGo away! Riko's head hurts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29824] = { id = 29824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Report: Like Jinyu in a Barrel", description = "With our leader turned to jade, our hozen guide disappeared, and a prisoner of war in tow, there was only one thing that Kiryn and I could do:\n\nMarch into our enemy's territory and deliver some vengeance.\n\nWant to know how it went?", sourceObjective = "Listen to Shokia's report.", progress = "I'm not quite done yet, {name}.", completion = "The most important thing we learned was that... not only have the Alliance befriended the jinyu, but they're giving them weapons, and teaching them how to use them.\n\nThe Alliance now control a force that outnumbers us thirty-to-one. And we - the HORDE - have befriended monkeys.", sourceObjectiveStatus = "unverified-source-field" }
quests[29825] = { id = 29825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pupil No More", description = "I once called Elder Nadox my teacher.\n\nThat changed forever when I was forced to watch him mercilessly slaughter my friends and family as a servant of the damned.\n\nFind him within the depths and make him pay for his crimes, {race}.", sourceObjective = "Seer Ixit in Ahn'Kahet has tasked you with the assassination of Elder Nadox.", progress = "Is the mighty Nadox dead for good?", completion = "With Nadox gone, I hope to take his place as a leader of my people.\n\nThe Empire of Azjol-Nerub is destined for greatness, {race}...", sourceObjectiveStatus = "unverified-source-field" }
quests[29826] = { id = 29826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Ahn'Kahet", description = "Prince Taldaram and his army of Scourge use the same wards we once used to hide our empire to keep themselves safe from the native denizens of the icy depths.\n\nDeactivate the wards and slaughter the Scourge guarding them. My forces will help the natives slaughter the rest.", sourceObjective = "Seer Ixit in Ahn'Kahet wants you to kill 3 Eyes of Taldaram, a Bonegrinder, and Prince Taldaram.", progress = "Much work remains to be done in Ahn'Kahet, even long after the Scourge are defeated.", completion = "Excellent.\n\n<You heard a series of clicking sounds.>\n\nNow to vanquish our other foe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29827] = { id = 29827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acid Rain", description = "Since you've been gone, more and more of these creatures are approaching our camp. They appear to be amassing for a major assault!\n\nWe're going to have to take some drastic measures if we hope to see tomorrow.\n\nHere, take my poisoned throwing stars and figure out a way to thin out their numbers.", sourceObjective = "Using the Recovered Gyrocopter, kill 25 Hozen Gutrippers and 25 Hozen Nibstabbers.", progress = "Well, {name}? Do we live to see another day?", completion = "Excellent! What a creative solution!\n\nThat should hold them off for a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[29828] = { id = 29828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Scourge Dred", description = "One of the fleeing Drakkari trolls told me of a great raptor king, Dred, that was immune to the plague.\n\nIf you could find King Dred and bring me one of his teeth, perhaps I could fashion it into a weapon.", sourceObjective = "Kurzel inside Drak'Tharon Keep wants you to slay King Dred and bring her his tooth.", progress = "Does the great beast exist?", completion = "<Kurzel's eyes open wide.>\n\nWow! That's enormous!", sourceObjectiveStatus = "unverified-source-field" }
quests[29829] = { id = 29829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discretion is Key", description = "Listen to me, {race}.\n\nIt's just been brought to my attention that there's been an incident at the Violet Hold. It would appear that the blues are launching a full scale invasion of Dalaran!\n\nI need you to get to the prison and speak with Lieutenant Sinclari at once. She'll give you the details.\n\nThat is not all. I need this handled with utmost discretion. We mustn't alarm the citizens of Dalaran if it can possibly be avoided. Do I make myself clear?\n\nVery well. Now, go!", sourceObjective = "Rhonin wants you to go to the Violet Hold in Dalaran and speak with Lieutenant Sinclari.", completion = "Not a moment too soon.\n\nAre you prepared to defend Dalaran, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[29830] = { id = 29830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containment", description = "My forces are in absolute shambles, and Malygos' assailants just keep coming.\n\nI fear that the worst has yet to come.\n\nYou must engage them until their leader, Cyanigosa, comes. Only her death will stop the invasion and save Dalaran.\n\nSpeak to me again when you are ready.", sourceObjective = "Lieutenant Sinclari in the Violet Hold wants you to put an end to the blue dragon invasion force. You are to speak to her again once Cyanigosa is slain.", progress = "Is it over? Were you able to withstand the assault?", completion = "Thank you, hero!\n\nDalaran is safe for another day because of your bravery.", sourceObjectiveStatus = "unverified-source-field" }
quests[29833] = { id = 29833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Business", description = "While it is true that the Prophet of Akali will trouble this world no more, there yet remains work to be done.\n\nThe greater part of Akali's blood has empowered another, and it is in him that the true danger lies.\n\nQuickly, {name}, make your way to Gundrak and speak with Tol'mar. He will be able to direct you further in this cause.", sourceObjective = "Har'koa wants you to speak with Tol'mar in Gundrak.", completion = "Lissen up, mon. Dere be dangerous work ta be done!", sourceObjectiveStatus = "unverified-source-field" }
quests[29834] = { id = 29834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah Must Pay", description = "It musta been da most awful thing I ever seen. Da great Akali - slain right before my eyes. Horrible...\n\nMy job be to observe only. But dis cannot stand! Gal'darah and his followers must pay!\n\nAvenge Akali's death, mon. It be da right thing ta do.", sourceObjective = "Tol'mar wants you to slay Slad'ran, Moorabi, and Gal'darah in Gundrak.", completion = "Ya done it?! Dey be no more?\n\nHere ya go, mon. Take dis gift for bringin' justice to da frozen wastes.", sourceObjectiveStatus = "unverified-source-field" }
quests[29835] = { id = 29835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah Must Pay", description = "Da mighty Akali has been slain, {race}.\n\nMy role in life be to record, not fight. But dis cannot stand! Gal'darah and his followers must pay!\n\nAvenge Akali's death, mon. It be da right thing ta do.", sourceObjective = "Chronicler Bah'Kini wants you to slay Slad'ran, Moorabi, and Gal'darah in Gundrak.", completion = "Ya really did it?\n\nYou surpassed my expectations, mon. Take dis gift for bringin' justice to da frozen wastes.", sourceObjectiveStatus = "unverified-source-field" }
quests[29836] = { id = 29836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Checkin'", description = "There have been fearsome sounds echoing from Gundrak. They have been increasing in volume and frequency of late.\n\nMy long-time student is currently recording events from inside Gundrak. Perhaps you could find the time to check in on her for me?", sourceObjective = "To'kini wants you to speak to Bah'kini in Gundrak.", completion = "To'kini be my cowardly father - too fearful to take up a position so near Gundrak... so he sent me!\n\nDis place be full of troll history. We can't let Gal'darah and his crazed followers keep it hidden forever!", sourceObjectiveStatus = "unverified-source-field" }
quests[29837] = { id = 29837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacred Scroll", description = "The unfamiliar markings on this parchment have an elegance about them that Yoggtord and his gang don't seem capable of.\n\nYou suspect that, like everything else these Hozu possess, this is stolen merchandise.\n\nPerhaps the original owner of the scroll is still nearby...", sourceObjective = "Bring the Illegible Scroll to Lorewalker Cho.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[29838] = { id = 29838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of a Kind", description = "At first glance, it be lookin' like da same old story here - trolls tappin' into forbidden powah by destroyin' da very beings dey should be worshippin'.\n\nIf what I learned be true, den dey have a special golem - one like nuthin' created before!\n\nBring me back a piece from dat golem ta study.", sourceObjective = "Chronicler Bah'Kini wants you to recover a piece of the Drakkari Colossus in Gundrak.", progress = "You get me a piece of dat golem, mon?", completion = "Ahh, yeah mon! Dat be what I'm lookin' for.\n\nHere ya go - take somethin' nice for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[29839] = { id = 29839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of a Kind", description = "Dis whole mess coulda been avoided if da Drakkari had worshipped da gods instead of destroyin' dem.\n\nI heard dat dey have a special golem - one imbued with forbidden powah.\n\nBring me back a piece from dat golem so we can learn from our bruddas and sistahs.", sourceObjective = "Tol'mar wants you to recover a piece of the Drakkari Colossus in Gundrak.", progress = "You find da golem? I'm sure it's in there somewhere.", completion = "Amazin'! Dis be like nothing I've ever seer before.\n\nGood work, mon.", sourceObjectiveStatus = "unverified-source-field" }
quests[29840] = { id = 29840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Posterity", description = "Gundrak looks doomed. You know dis to be true.\n\nIf you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end.\n\nPerhaps one day we be bringin' dem back to der former glory.", sourceObjective = "Chronicler Bah'Kini in Gundrak wants you to collect 6 Drakkari History Tablets.", progress = "You find da Drakkari history tablets, mon?", completion = "You be havin' my thanks, mon.\n\nThese will be very useful to us, I'm sure of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[29841] = { id = 29841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lay of the Land[TEMP]", description = "Grah!!\n\nFor every one of these muck-flingers we kill, another two spring from the woods to take its place. I wouldn't share this with the others, but it's clear that we won't last long here, {name}.\n\nI must stay and defend what remains of our belongings. You scout out the region and seek a solution to our primate problem.\n\nGo now. Our hope goes with you...", sourceObjective = "Explore the region.", sourceObjectiveStatus = "unverified-source-field" }
quests[29842] = { id = 29842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Answers", description = "<Cho endures your stream of questions before speaking.>\n\nSo much to ponder, traveler...\n\nYou first must learn how to ask before your mind can discern the truth.\n\nI have completed my meditations for today, but my candles remain at the Cairn of Blood.\n\nGo there. Clear your mind. We will speak again when you are prepared to hear my words.", sourceObjective = "Use the candles to meditate at the Cairn of Blood.", sourceObjectiveStatus = "unverified-source-field" }
quests[29844] = { id = 29844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Posterity", description = "Da land of da ice trolls is a shadow of its former glory.\n\nIf you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end.\n\nPerhaps one day we be givin' dis land back to a new line of frost trolls.", sourceObjective = "Tol'mar in Gundrak wants you to collect 6 Drakkari History Tablets.", progress = "You find da Drakkari history tablets, mon?", completion = "We trolls been subject to da splittin' of empires for longer than some races been existin'.\n\nWe always regrow from da ruins.", sourceObjectiveStatus = "unverified-source-field" }
quests[29847] = { id = 29847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Catch a Thief", description = "Just beyond this cave lies Ravenholdt Manor. You need to get inside without being seen!\n\n<Mostrasz places an enchantment on you.>\n\nThere - now I'll be able to keep an eye on you and communicate as you venture into the compound. Now sneak into that manor, locate the egg, and don't get caught...", sourceObjective = "Infiltrate Ravenholdt Manor and locate the missing black dragon egg.", completion = "So, you will join with me?\n\nGood. Very good.", sourceObjectiveStatus = "unverified-source-field" }
quests[29848] = { id = 29848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forlorn Watcher", description = "I would gladly give my life for the Makers or their creations.\n\nHowever, since Loken's betrayal it seems all of Ulduar has turned on the world. One in particular, the Maiden of Grief, seems to reel in agony at her new orders.\n\nPlease lay her to rest and bring me one of her tears.", sourceObjective = "Kaldir Ironbane in the Halls of Stone has asked you to put the Maiden of Grief to rest and to obtain a Crystal Tear of Grief.", progress = "I wish there were another way, but it seems death is the maiden's only salvation now.", completion = "<Kaldir stares into the crystal in silence for a moment.>\n\nNo being has ever felt such sincere sorrow as the Maiden of Grief has.\n\nLet us remember her spirit as we continue our efforts against Loken.", sourceObjectiveStatus = "unverified-source-field" }
quests[29850] = { id = 29850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupt Constructs", description = "The iron dwarves are busy at work carving out massive stone constructs that I fear will soon be used as powerful weapons.\n\nYou must defeat their overseer, Krystallus, and the dark rune giants already walking the halls before it is too late!", sourceObjective = "Kaldir Ironbane in the Halls of Stone has asked you to kill 3 Dark Rune Giants and Krystallus.", completion = "Well done, {race}.\n\nEvery weapon we can take away from Loken is a great boon to our own war effort.", sourceObjectiveStatus = "unverified-source-field" }
quests[29851] = { id = 29851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion of the Tournament", description = "With this tournament we grow ever closer to our final confrontation with the Lich King.\n\n{name}, fight with valor and honor. Every fighter here has gathered for the common good.\n\nTogether, we will stop Arthas!", sourceObjective = "Highlord Tirion Fordring has tasked you with the completion of the Trial of the Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[29860] = { id = 29860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diametrically Opposed", description = "I shall speak plainly to you, little {race}. My people have not been the same since our ties with Thorim were severed.\n\nVolkhan will not rest until either he, or we, are no more. We only want peace, but it seems we have no choice but war.", sourceObjective = "Stormherald Eljrrin in the Halls of Lightning wants you to defeat Volkhan.", completion = "Volkhan shall haunt the dreams of my people no more.\n\nContinue your efforts, little {race}. In time, I am certain my people will grow to forgive Thorim.", sourceObjectiveStatus = "unverified-source-field" }
quests[29861] = { id = 29861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whatever it Takes!", description = "One way or another, Loken shall fall.\n\nThe honor and glory of his defeat shall be yours.\n\nReturn to me with his lying tongue, and earn my unending gratitude.", sourceObjective = "Stormherald Eljrinn in the Halls of Lightning wants you to defeat Loken. You are then to return to Stormherald Eljrinn with Loken's Tongue.", progress = "Has justice been brought to Loken?", completion = "That vile worm is dead?\n\nYou have turned out to be a great boon to my people, little {race}.\n\nPlease accept this gift in return for your loyal friendship.", sourceObjectiveStatus = "unverified-source-field" }
quests[29862] = { id = 29862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Way", description = "Loken's forces prepare for war. What they are not ready for is to be attacked themselves.\n\nNow is the moment to strike. Take out General Bjarngrim and his army, lest they mount an offensive on all life on Azeroth!", sourceObjective = "Stormherald Eljrrin in the Halls of Lightning wants you to kill 3 Stormforged Menders, 3 Stormforged Tacticians, and General Bjarngrim.", progress = "Have you vanquished their forces?", completion = "Though few outside of us shall ever know it, you have certainly saved the world on this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[29863] = { id = 29863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormherald Eljrrin", description = "I have sent an emissary to the Halls of Lightning to take the battle to Loken.\n\nHe undoubtedly needs assistance, given the strength of Loken's armies. Lend him any aid you can so that we may finally stop the traitor.", sourceObjective = "King Jokkum wants you to enter the Halls of Lightning and speak with Stormherald Eljrrin.", completion = "Our time to act is short. Loken prepares for war.", sourceObjectiveStatus = "unverified-source-field" }
quests[29864] = { id = 29864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Working at the Source", description = "We are hard at work ensuring that we minimize our losses to the Scourge war machine.\n\nThe vrykul here are undermining that mission by willingly joining the Lich King's ranks.\n\nPlease, brave champion, you must defeat their spiritual leader, Svala, before she leads her people into the eternal shadow!", sourceObjective = "Argent Confessor Paletress wants you to slay Svala Sorrowgrave.", progress = "I have faith in you, {name}.", completion = "Every soldier we deny to the Scourge is more than one life saved.\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29865] = { id = 29865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silkwood Road", description = "West of here is the Silkwood Road. It has fallen into shadow as the spiders there have turned to a more evil and gluttonous path.\n\nI would face these villains myself but someone has to defend the noodle shop from... um... dangers and such.\n\nGo, hero, and conquer these beasts! Should you succeed perhaps I shall regale you with some of my epic tales of heroism.\n\nI'll also pay you.", sourceObjective = "Defeat 8 Silkwood Stalkers.", progress = "The silkwood stalkers are not in balance with nature. Predators are one thing but these creatures kill for pleasure. Harmony must be restored.", completion = "Such a noble hero. You remind me of a younger, less good looking version of myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[29866] = { id = 29866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Threads that Stick", description = "Ah, welcome traveler. I have need of your services!\n\nSyra Goldendraft was looking for some silk. Personally I hate silk as it always gets stuck in my fur.\n\nI really want to impress her though.\n\nIf you bring me some silk from the Silkwood to the west of here I will gladly pay you for your help.", sourceObjective = "Gather 7 Pristine Silk Strands.", progress = "Did you find the Silkwood?", completion = "Oh thank you so much! This is perfect!\n\nI hope it didn't stick to you like it stuck to me.\n\nI'm going to go find Syra and give this to her right away!", sourceObjectiveStatus = "unverified-source-field" }
quests[29871] = { id = 29871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clever Ashyo", description = "I'm not sure where Clever Ashyo got his \"Clever\" title from. All jinyu are clever, and I wouldn't say that he's any more clever than most of them.\n\nQuite the opposite, actually.\n\nAt least he's a capable fighter. He did well enough at Tian Monastery to be selected for our training mission.\n\nIf you want to help him look for the Hidden Master, you can find him along the Valley's northern border.", sourceObjective = "Find Clever Ashyo.", completion = "Where have I seen you before?", sourceObjectiveStatus = "unverified-source-field" }
quests[29872] = { id = 29872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lin Tenderpaw", description = "Lin is more talented than she thinks she is. Strong of fist but weak of spirit. With more confidence, she could be better than all of us.\n\nPerhaps she will find the surety she needs on her trip into the west. She's probably on her way to Stoneplow as we speak. Stop and speak to her, if you find yourself on that side of the Valley.", sourceObjective = "Find Lin Tenderpaw.", completion = "Oh, it's you!\n\nNo, I haven't found the Hidden Master yet. I probably wasted my time coming out here.\n\n<Sigh...>", sourceObjectiveStatus = "unverified-source-field" }
quests[29873] = { id = 29873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ken-Ken", description = "So... Ken-Ken. The hozen.\n\nPersonally, I'm impressed he's progressed so far in his training. He's got a brain between his ears, which is more than can be said for most of his kind.\n\nHe said he was headed east, but, seeing as we're already on the far east side of the valley, I can't imagine he went too far from here. Look for him at Zhu's Watch, in Krasarang Wilds, down the path to the south. See what he's found.", sourceObjective = "Find Ken-Ken.", completion = "This place... it... it so SAD!\n\nKen-Ken never seen a place so sad.", sourceObjectiveStatus = "unverified-source-field" }
quests[29874] = { id = 29874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kang Bramblestaff", description = "Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds.\n\nI wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave {race} was looking out for him.", sourceObjective = "Find Kang Bramblestaff.", completion = "I'm pretty sure this settlement wasn't here a few weeks ago. Where did these people come from?", sourceObjectiveStatus = "unverified-source-field" }
quests[29875] = { id = 29875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kang Bramblestaff", description = "Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds.\n\nI wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave {race} was looking out for him.", sourceObjective = "Find Kang Bramblestaff.", completion = "I'm pretty sure this settlement wasn't here a few weeks ago. Where did these people come from?", sourceObjectiveStatus = "unverified-source-field" }
quests[29877] = { id = 29877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Poor Grasp of the Basics", description = "Virmen - they no just eat our food. They trying to start farms of their own. The problem is... well, they ookin' dumb.\n\nYou no believe Muno? Last night, they break into tool sheds... steal equipment. When we wake up, we find rakes and wheelbarrows planted in ground.\n\nThey was WATERING them. They was trying to GROW WHEELBARROWS.\n\nPlease, while you out there, unbury our stuff.", sourceObjective = "Unearth 7 pieces of farm equipment.", progress = "Man, those virmen is dumb.", completion = "Thanks, friend. Now maybe a hozen can get some ookin' work done around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[29879] = { id = 29879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swallowed Whole", description = "Now, back to your dilemma.\n\nI believe you can help your people build relations with our hozen, as my people have.\n\nThe trail behind me will lead you to a body of water the hozen use to gather the fish that feeds them.\n\nAround this time every year, fearsome beasts call those waters home and many hungry hozen are lost to them.\n\nIf you were to rescue some of the victims and gather some fish, perhaps you will be regarded more favorably.", sourceObjective = "Free 5 hozen from the Engorged Crocolisks, and gather 5 Speckled Trout from Lake Kittitata.", progress = "Wikket got slickies... for me!?", completion = "Wikket save hozen? And bring slickies?\n\nHmm, maybe wikket not so bad.\n\nTooki Tooki never liked Dook Ookem anyway...", sourceObjectiveStatus = "unverified-source-field" }
quests[29881] = { id = 29881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Color", description = "As you have seen, this grove is abundant with beautiful pink petals.  As each petal ages, the tone deepens and fades.\n\nIf you would be so kind, I am in need of a few petals that have freshly fallen.  Only the ones that have just fallen will have precisely the right color I am after.\n\nFrom it I can forge an ink that will be breathtaking.  Can you help me?", sourceObjective = "Gather 8 Freshly Fallen Petals.", progress = "There is only a small window of time after each petal falls that it may be used to achieve the perfect hue.", completion = "Ah! You have a wonderful eye for color my friend.  These will make a superb pigment.", sourceObjectiveStatus = "unverified-source-field" }
quests[29882] = { id = 29882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quill of Stingers", description = "To achieve perfect paint strokes, one must have the right tools. My own have fallen into disrepair, their bristles becoming as unmanageable as hozu hair.\n\nHave you seen the wasps throughout the Arboretum? Their stingers can be fashioned into quills that provide just the right level of sharpness in each line.\n\nCould you gather some for me please?", sourceObjective = "Gather 6 Wasp Stingers from Orchard Wasps.", progress = "Have you been able to acquire some stingers? I would normally ask a monk for help with this but they all seem to be elsewhere at the moment.", completion = "My thanks traveler. These will make a fine set of quills. Here is something for your trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[29883] = { id = 29883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pearlfin Situation", description = "I've been thinking.\n\nWe are cut off from support and a long way from home.\n\nAlthough these Pearlfin jinyu mistrust our presence, they do not appear to be hostile.\n\nIf we could convince them that we are their friends, an alliance between our races could prove extremely valuable.\n\n{name}, you must go speak to the jinyu around the village.\n\nConvince their leaders that we are not to be feared, and that we only wish for peace.", sourceObjective = "Speak to Elder Lusshan, Pearlkeeper Fujin, Instructor Sharpfin, and Ot-Temmdo at Pearlfin Village.", progress = "If we can win over the jinyu, they may allow us to stay.", completion = "It sounds like you made quite the good impression.\n\nWell done, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29885] = { id = 29885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Road Rations", description = "We do not have time to wait around for the Admiral to recover.\n\nSully and I are planning to search for Anduin to the north, but we'll need supplies for our journey.\n\nThe lake here is teeming with wildlife, which we have received permission to hunt.\n\nGo and gather some supplies while Sully and I finalize our preparations.", sourceObjective = "Collect 6 Tortoise Flanks.", progress = "Time is short. Each hour we delay, the White Pawn may move further away.\n\nWhere are the supplies I asked for?", completion = "This should be plenty, {name}. Thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[29886] = { id = 29886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen Healing", description = "Your friend Taylor is in critical shape. Unfortunately, his wounds are tainted by hozen poison, which is very difficult to cure.\n\nLuckily, through many generations of fighting the hozen, my people have developed medicines to treat such injuries.\n\nThe flowers growing on the surface of Glass Lake are needed to make the antidote.\n\n{name}, go quickly and bring back some blooms. Your Admiral's life depends on it.", sourceObjective = "Collect 6 Zen Lotus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29887] = { id = 29887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elder's Instruments", description = "Oh dear, oh dear... The Elder mustn't find out!\n\nI must have left the Elder's ceremonial instruments behind during the escape.\n\nBut... Moonwater Retreat is crawling with hozen by now!\n\nWhat sort of Pearlkeeper am I, to have lost them so carelessly?\n\n<The old jinyu buries his face into his hands.>\n\nStranger, could you find it in your heart to help me?", sourceObjective = "Collect the Waterspeaker's Staff, Ceremonial Robe, Jade Crown, and Rosewood Beads from Slingtail Stickypaws.", progress = "The Elder is a Waterspeaker. He speaks to the waters, and they answer.", completion = "You found them? Oh thank the spirits of water!\n\nYou have saved my tailfin, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29888] = { id = 29888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out the Lorewalker", description = "I see that you and your people are desperate to find your Prince Anduin.\n\nI know someone who may be able to help you, a pandaren Lorewalker who knows this land better than anyone. I cannot guarantee what kind of reception you will receive, but he will almost certainly be as curious about you as you are of him!\n\nThe Lorewalker lives in the forest to the southwest. Tell him that the Pearlfin have sent you.", sourceObjective = "Search for Lorewalker Cho at the Dreamer's Pavilion in the Jade Forest.", completion = "You look around the empty house.\n\nIt appears you are in the right place, but there is no sign of its inhabitant.", sourceObjectiveStatus = "unverified-source-field" }
quests[29889] = { id = 29889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borrowed Brew", description = "A delicious smell wafts out from the bottle on the table.\n\nA little taste couldn't hurt, right?", sourceObjective = "Taste the mouthwatering brew.", completion = "I heard your people had washed up on our shores, but I did not expect to find one washed up on my very doorstep! What brings you here, stranger?\n\n<You explain about your search for Prince Anduin, and describe the boy to the pandaren.>\n\nVery interesting! And so the Pearlfin sent you to me, did they?", sourceObjectiveStatus = "unverified-source-field" }
quests[29890] = { id = 29890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Your Center", description = "The dream brew is complete! This time, when you drink it, you must embrace the visions you see from a state of inner focus.\n\nFollow me to my pagoda, and I will teach you how to achieve the inner calm that we pandaren value so much.\n\nYour troubled mind will present you with many distractions, but just remember to stay centered!", sourceObjective = "Meditate with Lorewalker Cho at the pagoda at the Dreamer's Pavilion in the Jade Forest.", completion = "How did you find me?\n\n<Anduin listens to you describe the vision from the Dream Brew.>\n\nRemarkable! That's exactly what happened several days ago. We've been laying low since then.", sourceObjectiveStatus = "unverified-source-field" }
quests[29891] = { id = 29891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potency", description = "To make the Dream Brew, we will need several ingredients.\n\nFirst, to improve its strength, I will need an ingredient from a fearsome creature, the legendary Mist Horror.\n\nIt is said that this creature only appears where the fog is deepest.\n\nNorth and east of here, you will find smaller Mist Creepers roaming the swamps. Kill these creatures until the Mist Horror appears, and then bring me its heart.", sourceObjective = "Kill Mist Creepers until a Mist Horror appears, then collect a Mist Horror Heart.", progress = "The mists seem to have a mind of their own, do they not?", completion = "This is an amazing specimen! I am quite shocked that you have succeeded, actually.", sourceObjectiveStatus = "unverified-source-field" }
quests[29892] = { id = 29892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Body", description = "A brew's body is an important and often overlooked factor.\n\nTo create the perfect consistency, I will need pristine eyes from the Bog Crocolisks to the east.\n\nTake care. The creatures are quite vicious.", sourceObjective = "Collect 5 Pristine Crocolisk Eyes from Bog Crocolisks.", progress = "Watch your step in the swamp, my new friend.", completion = "Do you have crocolisks where you are from?", sourceObjectiveStatus = "unverified-source-field" }
quests[29893] = { id = 29893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hue", description = "The most distinguishing feature of the Dream Brew is its iridescent, dream-like color.\n\nTo the east, you will find Glittering Amberflies. I will need their wings to create the final luminescent color of the brew.\n\nTake this knife and use it to collect 8 wings.", sourceObjective = "Collect 8 Amberfly Wings.", progress = "Have you collected all the ingredients? It is almost time to make the Dream Brew.", completion = "Beautiful color, rare transparency, shimmer but not sparkle...these will do quite well.\n\nI am beginning to see great potential in you, strange one.", sourceObjectiveStatus = "unverified-source-field" }
quests[29894] = { id = 29894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of the Water", description = "Our war against the hozen rages without end, and the future of our tribe is uncertain.\n\nThis is why our waterspeaker has decided to seek wisdom from the waters.\n\nElder Lusshan is waiting. Please deliver the instruments so that they may begin.", sourceObjective = "Speak to Elder Lusshan and witness the waterspeaking ceremony.", progress = "<The Elder's eyes are glazed over. His vision is cast inward, toward the wisdom he has gained.>", completion = "I saw the vision, {name}. What do you think it means?\n\nI think it is clear that you play some part in it.", sourceObjectiveStatus = "unverified-source-field" }
quests[29895] = { id = 29895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trail of the White Pawn", description = "Although the cloak is ragged and torn, there is no mistaking the fine tailoring and the King's royal crest.\n\nYou should show it to your Alliance commander.", sourceObjective = "Show the cloak to Admiral Taylor at Pearlfin Village in the Jade Forest.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[29898] = { id = 29898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacred Waters", description = "I appreciate you coming all this way to save me, but Ren is gravely injured.\n\nThe old pandaren had no reason to help me, yet still he risked his life to save my own.\n\nBefore the fever set in, he mentioned that there are healing waters in the cave just down the hill.\n\nIt is dangerous, but I will do anything to help my friend. Will you help me retrieve the waters?", sourceObjective = "Collect healing waters from the four Sacred Bowls in the Den of Sorrow.", progress = "Perhaps I could bring some of these healing waters back to Stormwind with me.", completion = "The healing waters should abate Ren's fever for a short while, but alas, I fear it is no permanent cure.\n\nThank you, {class}. We have granted him a little more time, at least.", sourceObjectiveStatus = "unverified-source-field" }
quests[29899] = { id = 29899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rest in Peace", description = "The spirits... the cavedwellers... they howl in agony... \n\nTrapped... in this world... cannot move... to the next.\n\nI... will go mad... listening... to their cries... \n\nPlease...go...put them to rest.", sourceObjective = "Kill 6 Tortured Spirits.", completion = "Thank you... friend. I am... happy... knowing... the spirits... are at peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[29900] = { id = 29900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Legend", description = "My father has dedicated his life to studying the Vale of Eternal Blossoms.\n\nThe Vale is a mythical place, sealed after the Pandaren revolution twelve thousand years ago. We know so little about it!\n\nMy father followed a trail of clues to the cave down the hill, seeking a very old poem known as the Song of the Vale, but he is in no condition to retrieve it. It is guarded by some sort of ancestor spirit.\n\nIf you are heading that way anyway, would you mind bringing it back to him?", sourceObjective = "Retrieve the Song of the Vale from the Den of Sorrow.", progress = "Did you... find the scroll?", completion = "Oh... it is the poem! Did you... read it? What did you learn about the Vale?", sourceObjectiveStatus = "unverified-source-field" }
quests[29901] = { id = 29901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anduin's Decision", description = "You have done all you can for the Prince's friends.\n\nYou completed your mission and found the White Pawn - Prince Anduin. Admiral Taylor and the other SI:7 agents will be eager to have the boy safe in their custody.\n\nIt is time to return home.", sourceObjective = "Tell Anduin that it is time to return home.", progress = "What? You lost the boy?", completion = "He did WHAT?!?!?\n\nHe's lucky that I haven't found him yet, because when I do, I just might kill him myself!\n\nWhatever he thinks he's doing... chasing after this Vale... it is not behavior fit for a prince!\n\nIf we didn't have more pressing matters at hand, I would send our entire fleet chasing after his heels!", sourceObjectiveStatus = "unverified-source-field" }
quests[29903] = { id = 29903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Match", description = "Elder Lusshan and I agree that the best path forward will be to work together.\n\nWe will share with the Pearlfin our superior military knowledge and weaponry.\n\nIn return, they will be a powerful ally should we again encounter the Horde.\n\nTake this crate of equipment and weapons. I need you to go around the village and equip the jinyu with weapons befitting their skills.", sourceObjective = "Speak to Pearlfin Aqualytes and arm them with the proper equipment.", progress = "The jinyu are skilled in different ways. It is up to us to find their strengths.", completion = "Good. Let those Horde mongrels show their faces now!", sourceObjectiveStatus = "unverified-source-field" }
quests[29904] = { id = 29904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bigger Fish to Fry", description = "I've prepared a team of bright young Pearlfin trainees who need field experience.\n\nTake them northeast, into the Bamboo Wilds, and kill any wildlife that you find.\n\nDon't bring them back until they're fit for battle.", sourceObjective = "Train the Pearlfin Adepts by killing 24 wildlife in the Bamboo Wilds.", progress = "How are those trainees looking?", completion = "Your trainees returned recently. I could hardly believe my eyes! They did not look like the same jinyu that you left with.\n\nExcellent work, {class}. Couldn't have done better myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[29905] = { id = 29905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Them Burn", description = "Advance scouts report that the hozen at the Slingtail Pits are amassing with reinforcements from their tribes to the north.\n\nOur forces are gathered for battle on the ridge to the northwest. They are just waiting for you.\n\nNow is the time to show them what we are made of. Now is the time to destroy them indefinitely.", sourceObjective = "Kill 15 Grookin Reinforcements or Slingtail Recruits.", completion = "The waters were right about you, {name}. Because of your efforts, this village has a future. We will not forget the lessons you've taught us, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29906] = { id = 29906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carp Diem", description = "Despite the hozen's apparent disarray, there is an order to their chaos. Their leader, Chief Gukgut, is the shrewd mastermind behind their attacks.\n\nHe is organizing their movements at the great pit at the hozen camp to the northwest.\n\nStrike now and show him no mercy, {name}, for he will do the same.", sourceObjective = "Kill Chief Gukgut.", completion = "Without their leader, these hozen should once again settle into disarray.\n\nToday we rejoice in our victory! {name}, you came to us a stranger, but you depart as a friend.\n\nFrom henceforth, you are the highest of the high - a valued friend and defender of the Pearlfin tribe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29907] = { id = 29907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chen and Li Li", description = "My niece and I are new to Pandaria. Probably like yourself. We're visitors from the Wandering Isle, and, to be honest, we have no idea where we're going.\n\nThat farm up ahead looks as fine a place as any to take off our shoes and enjoy a brew. What do you say, Li Li?\n\n{race}? Would you like to share the road with us?", sourceObjective = "Follow Chen Stormstout to Pang's Stead.", progress = "Yes?", completion = "Welcome, welcome, visitors! You've come to sample some of my son's turnips? Perhaps purchase a few pigs?\n\nPlease, make yourselves at home. I have plenty of room.", sourceObjectiveStatus = "unverified-source-field" }
quests[29908] = { id = 29908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Seemingly Endless Nuisance", description = "I apologize for the state of things around here. The virmen - those rabbity creatures, down the hill - have been pushing further and further into my family's farm, and our crops - which are normally bigger, and more delicious, by the way - have been suffering because of it.\n\nI'm no soldier... but you might be! Would you mind pushing some of these virmen off of our land?", sourceObjective = "Slay 8 Snagtooth Spotters, Tool-Grabbers, or Troublemakers. Then slay 18 Snagtooth Pesterlings.", completion = "<Pang surveys the area around his farm.>\n\nWell, they're not ALL gone yet, but there's less of them. And they aren't holding their ears quite as high anymore.\n\nI'd guess that they're scared of you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29909] = { id = 29909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Low Turnip Turnout", description = "Your help here is appreciated, {name}. I'd like to give you another job, if you're interested.\n\nMy son, Ang, runs the small farm just down this hill. He should have brought me some fruits and vegetables this morning, but I haven't seen him all day.\n\nWould you go down there and see what's going on?", sourceObjective = "Find Ang Thunderfoot.", completion = "Wha-? Who the...? My father sent you?\n\nPshh... he can be so nosy sometimes. I have everything under control here.", sourceObjectiveStatus = "unverified-source-field" }
quests[29910] = { id = 29910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rampaging Rodents", description = "I went off this morning to watch my papa fight the virmen. When I came back, the farm was full of marmots!\n\nI don't want to kill them, but we need to get rid of them. Hey, I know! We can close the holes!\n\nFill in their holes with dirt, so they can't come out in our farm anymore.", sourceObjective = "Move 6 Plump Marmots off of Thunderfoot Farm, and fill in 6 Marmot Holes.", progress = "The marmots won't be happy when you try to fill in their holes.", completion = "Thank you, sir! Now I can get back to my chores.", sourceObjectiveStatus = "unverified-source-field" }
quests[29911] = { id = 29911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Practically Perfect Produce", description = "Here, {name}. My father will be wanting this.\n\nThank you, again, for helping with the virmen.", sourceObjective = "Bring the Crate of Fresh Crops to Pang Thunderfoot.", progress = "Do I smell turnips?", completion = "Ho ho! Now that's what I like to see!", sourceObjectiveStatus = "unverified-source-field" }
quests[29912] = { id = 29912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fabulous Miss Fanny", description = "Most of these vegetables will be sold, but I'd like to keep some for my family. Specifically, my nephew Liang needs some to feed to his pigs.\n\nUnfortunately, the pathway to Liang's farm is currently swarming with Snagtooth virmen. We're going to have to ask Miss Fanny to help us out.\n\nBring some of the food we've gathered to Miss Fanny, who stands next to my house. Then ask her - NICELY! - to send them down to Liang's ranch.", sourceObjective = "Bring Ang's Giant Pink Turnip, Ang's Summer Watermelon, and Pang's Extra-Spicy Tofu to Miss Fanny, and ask her to deliver them. The food must land on Thunderfoot Ranch.", progress = "Not now, neighbor. I need to scrounge up some food for these pigs.", completion = "I understand you're the one who sent the food down from uncle's farm. Thank you.\n\nMy pigs are picky eaters, but those turnips and watermelons are some of their favorites.", sourceObjectiveStatus = "unverified-source-field" }
quests[29913] = { id = 29913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Meat They'll Eat", description = "I told you earlier, my pigs are picky eaters. They need to eat meat to grow strong, but they don't like mutton, they don't like yak, and I'm not about to feed them any pig meat.\n\nThey do, however, eat meat off of the mushan beasts, and they're also quite partial to turtle. Both creatures can be found in abundance to the west.\n\nMy skills as a hunter are admittedly quite weak. Can you help out a young rancher and his pigs?", sourceObjective = "Obtain 4 Mushan Shoulder Steaks and 80 Turtle Meat Scraps.", progress = "It hurts my ears to hear their hungry squeals.\n\nOnce you've been a pig rancher for a while, you can distinguish hungry squeals from regular squeals.", completion = "<Liang sorts through the meat.>\n\nYou're not just a {class}, but you're a butcher, too? You've got an eye for quality pig food, neighbor.", sourceObjectiveStatus = "unverified-source-field" }
quests[29914] = { id = 29914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Sty", description = "I try to keep an eye on my stock, but every once in a while some of them sneak away. With all the confusion these virmen are causing, I may have let my guard down for a few moments, and some of my pigs escaped.\n\nCare to look for them? I'd start by looking down the hill, to the west.", sourceObjective = "Find Jian, Ling, and Smelly.", progress = "Have you found them? There should be three missing, I think.", completion = "There they are! Back into the sty with you three, now!\n\n<Liang looks up at you.>\n\nThank you, neighbor. I'm truly grateful for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[29915] = { id = 29915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Neighbor's Duty", description = "I'm not the only one having trouble with his stock, it seems. One of Francis' sheep has wandered over to my ranch, for the third time this week. I'm beginning to think he needs help tending to his flock.\n\nYou should check up on him, neighbor. And bring this poor little thing with you.", sourceObjective = "Bring the Wayward Lamb to Francis the Shepherd Boy.", progress = "Oh... you have one of my... my lambs?", completion = "You really shouldn't have brought the lamb back to me. He... he was safer in that pigsty than he is over here.", sourceObjectiveStatus = "unverified-source-field" }
quests[29916] = { id = 29916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piercing Talons and Slavering Jaws", description = "First the hawks came. You've probably seen some of them circling up above.\n\nThe wolves came shortly after. I think they smelled my weakness.\n\nI'm not nearly as brave as Master Shang thought I was. The master will be quite cross with me if I don't do something about these beasts.\n\nCan... can you help, <sir/ma'am>?", sourceObjective = "Kill 5 Thieving Plainshawks and 6 Thieving Wolves.", progress = "I wish I were brave enough to fight them, but...", completion = "They... they're not stopping, but at least we fought back. Right?", sourceObjectiveStatus = "unverified-source-field" }
quests[29917] = { id = 29917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lupello", description = "I've been thinking... the wolves might stop attacking if we kill their pack leader.\n\nWe call him Lupello, and he patrols the opposite riverbank.\n\n<Francis' concentration is broken by another attack. Perhaps you should go deal with Lupello yourself.>", sourceObjective = "Slay Lupello.", progress = "What will Master Shang say when he finds out?", completion = "I know I should be the one fighting them off. Maybe I'm not cut out for shepherding after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[29918] = { id = 29918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Bravery", description = "<Master Shang speaks to his shepherd boy.>\n\nFrancis, you need to show bravery! You have everything it takes to make a great shepherd, except the courage to face your fears!\n\n<He looks over to you.>\n\nYou, stranger. You helped the rest of my family. Francis is like a second son to me.\n\nShow my apprentice what it means to lack fear. Use this rope to lasso and defeat one of the great white hawks above us.\n\n<Shang points to the sky, looks at Francis, and leaves.>", sourceObjective = "Use the Rancher's Lariat to lasso and defeat a Great White Plainshawk.", progress = "You lack fear. I can sense it in your heart.", completion = "Francis has taken longer than I expected to become an effective shepherd. We all go through these phases... my son Liang was weak once, too. As was I.\n\nBut he will learn. It is the Thunderfoot way.", sourceObjectiveStatus = "unverified-source-field" }
